types.schema_json:
{
  "name": "Config",
  "package": "harness",
  "description": "Config is the harness Job's runtime configuration, read from the pod\n environment through the generated from_env_var helper.",
  "fields": [
    {
      "name": "fqdn",
      "type": "string",
      "description": "fqdn is the fleet's public hostname (e.g. \"dev.seabeam.net\"). Every door\n the harness uses is https://\u003cfqdn\u003e/..., validated against the public\n certificate.",
      "required": true,
      "constraints": [
        "maximum size: 253 bytes",
        "minimum size: 1"
      ],
      "constraint_infos": [
        {
          "rule": "assert_required",
          "target": "field",
          "value_kind": "bool",
          "bool_value": true,
          "source": "annotation"
        },
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 253,
          "unit": "bytes",
          "source": "annotation"
        },
        {
          "rule": "assert_min_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 1,
          "unit": "bytes",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "profile",
      "type": "enum",
      "description": "profile selects the scenario set.",
      "enum_values": [
        {
          "name": "PROFILE_GATE",
          "number": 1,
          "description": "GATE is the non-destructive set that gates promotion to pilot."
        },
        {
          "name": "PROFILE_DESTRUCTIVE",
          "number": 2,
          "description": "DESTRUCTIVE is pod kill, PVC wipe and cold restart. Dev only."
        }
      ]
    },
    {
      "name": "expected_digests",
      "type": "string",
      "description": "expected_digests are the image digests the pipeline deployed. The report\n echoes them so the promotion gate can match a run to a digest set.",
      "repeated": true,
      "constraints": [
        "maximum size: 64 elements",
        "maximum element size: 256 bytes"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 64,
          "unit": "elements",
          "source": "annotation"
        },
        {
          "rule": "assert_element_max_size",
          "target": "element",
          "value_kind": "int",
          "int_value": 256,
          "unit": "bytes",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "trace_id",
      "type": "string",
      "constraints": [
        "maximum size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
    },
    {
      "name": "noop",
      "type": "bool"
    }
  ]
}

{
  "name": "Config",
  "package": "schematicctl",
  "description": "Config is one named connection profile.",
  "fields": [
    {
      "name": "connection",
      "type": "message",
      "description": "connection is the gRPC connection configuration: gateway endpoints, the\n cred-pair private key, and the CAs to trust.",
      "message": {
        "name": "Config",
        "package": "grpcconfig",
        "description": "Config is the single configuration type for all services.\n\n Bootstrap fields (endpoints, instance_id, private_key, trusted_cas) are loaded\n from YAML at boot and used to connect to the cluster.\n\n Runtime fields (ping_interval_ms, rebalance_interval_ms, listen_address,\n max_request_size, request_timeout_seconds, logger, shutdown_timeout_seconds)\n are delivered by the cluster via ServiceConfigState and can change at any time.\n\n TLS certificates are obtained automatically by the servicemanager via X509Mint\n after token exchange — they are not part of the config.",
        "fields": [
          {
            "name": "endpoints",
            "type": "message",
            "description": "Cluster endpoints. Set in bootstrap file; can be updated at runtime\n via ServiceConfigState to add/remove endpoints dynamically.",
            "repeated": true,
            "constraints": [
              "maximum size: 32 elements"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32,
                "unit": "elements",
                "source": "annotation"
              }
            ],
            "message": {
              "name": "Host",
              "package": "host",
              "description": "Host identifies a network endpoint by hostname/IP and port.\n The host field accepts either an FQDN or an IP address (v4/v6).",
              "fields": [
                {
                  "name": "host",
                  "type": "string",
                  "description": "Hostname or IP address (e.g. \"api.example.com\" or \"10.0.0.1\").",
                  "required": true,
                  "constraints": [
                    "must be a valid hostname or IP address",
                    "maximum size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_host",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "default_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "port",
                  "type": "int32",
                  "description": "Port number (1-65535).",
                  "constraints": [
                    "must be a valid network port (1-65535)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_net_port",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "protocol",
                  "type": "enum",
                  "description": "Transport protocol. Default TCP (zero value).",
                  "enum_values": [
                    {
                      "name": "TCP",
                      "number": 0
                    },
                    {
                      "name": "UDP",
                      "number": 1
                    }
                  ]
                }
              ]
            }
          },
          {
            "name": "instance_id",
            "type": "string",
            "description": "instance_id uniquely identifies this running instance/replica.\n Used for leader elections on boundaries with (spec.leader) = true.\n If empty, a random ID is generated at client creation time.",
            "constraints": [
              "maximum size: 128 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 128,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "private_key",
            "type": "message",
            "description": "private_key is used to mint throwaway bootstrap JWTs for the\n token exchange flow. The kid is in private_key.id;\n identity (subject/audience) comes from the delegate looked up\n by TokenExchanger using the matching kid.\n If absent, cloud-native authentication is attempted.",
            "message": {
              "name": "Key",
              "package": "key",
              "description": "Key represents a private cryptographic key (alias for ProtoKey).",
              "fields": [
                {
                  "name": "id",
                  "type": "string",
                  "description": "Id is a unique identifier for the key (corresponds to kid in JWK)",
                  "required": true,
                  "constraints": [
                    "maximum size: 256 bytes",
                    "minimum size: 1"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 256,
                      "unit": "bytes",
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_min_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 1,
                      "unit": "bytes",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "base64",
                  "type": "string",
                  "description": "Base64 contains the base64url-encoded PEM private key block",
                  "required": true,
                  "constraints": [
                    "must be base64 encoded",
                    "encoding type: ENC_TYPE_KEY_PRIVATE_ANY",
                    "maximum size: 16384 bytes"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 16384,
                      "unit": "bytes",
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_base64",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_enc_type",
                      "target": "field",
                      "value_kind": "enum",
                      "enum_value": "ENC_TYPE_KEY_PRIVATE_ANY",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "created",
                  "type": "int64",
                  "description": "Created is the Unix epoch timestamp (seconds) when the key was created\n Valid range: 1735689600 (2025-01-01) to 8045740800 (2225-01-01)",
                  "required": true,
                  "constraints": [
                    "must be \u003e= 1735689600",
                    "must be \u003c= 8045740800"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_ge",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 1735689600,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_le",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 8045740800,
                      "source": "annotation"
                    }
                  ]
                }
              ]
            }
          },
          {
            "name": "ping_interval_ms",
            "type": "int32",
            "description": "ping_interval_ms controls how often each endpoint is pinged for latency measurement.\n Default: 5000 (5 seconds)",
            "default": 5000
          },
          {
            "name": "rebalance_interval_ms",
            "type": "int32",
            "description": "rebalance_interval_ms controls how often the active connection is re-evaluated\n based on latency. Default: 10000 (10 seconds)",
            "default": 10000
          },
          {
            "name": "listen_address",
            "type": "message (recursive reference: host.Host)",
            "description": "listen_address is the bind address for the gRPC server. Default port 8443.",
            "required": true,
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              }
            ]
          },
          {
            "name": "max_request_size",
            "type": "int64",
            "description": "max_request_size is the maximum request size in bytes.\n Must be greater than 0. Default: 10MB (10485760 bytes)",
            "default": 10485760,
            "constraints": [
              "must be \u003e 0"
            ],
            "constraint_infos": [
              {
                "rule": "assert_gt",
                "target": "field",
                "value_kind": "int",
                "int_value": 0,
                "source": "annotation"
              }
            ]
          },
          {
            "name": "request_timeout_seconds",
            "type": "int64",
            "description": "request_timeout_seconds is the timeout for client requests.\n Must be positive. Default: 30 seconds.",
            "default": 30,
            "constraints": [
              "duration constraint: DURATION_TYPE_POSITIVE"
            ],
            "constraint_infos": [
              {
                "rule": "assert_duration",
                "target": "field",
                "value_kind": "enum",
                "enum_value": "DURATION_TYPE_POSITIVE",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "logger",
            "type": "message",
            "description": "logger configures the logger for the service.\n Controls log format (JSON/console), level, output paths, and more.",
            "message": {
              "name": "LoggerConfig",
              "package": "logger",
              "description": "LoggerConfig represents the configuration for a logger instance.\n It controls the output format, verbosity level, and formatting options.\n\n Example usage:\n   - Development mode with console output and pretty printing for local debugging\n   - Production mode with JSON output and no pretty printing for log aggregation",
              "fields": [
                {
                  "name": "name",
                  "type": "string",
                  "description": "Name is the logger name/component identifier",
                  "constraints": [
                    "maximum size: 128 bytes"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 128,
                      "unit": "bytes",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "format",
                  "type": "enum",
                  "description": "Format determines the output format for log messages (JSON or console)\n Default: FORMAT_JSON in production, FORMAT_CONSOLE in development",
                  "constraint_infos": [
                    {
                      "rule": "assert_enum_defined",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    }
                  ],
                  "enum_values": [
                    {
                      "name": "FORMAT_JSON",
                      "number": 1,
                      "description": "FORMAT_JSON outputs logs as JSON objects, ideal for structured logging and log aggregation systems"
                    },
                    {
                      "name": "FORMAT_CONSOLE",
                      "number": 2,
                      "description": "FORMAT_CONSOLE outputs logs in a human-readable console format, ideal for development and debugging"
                    }
                  ]
                },
                {
                  "name": "level",
                  "type": "enum",
                  "description": "Level sets the minimum severity level for log messages to be output\n Messages below this level will be filtered out\n Default: LEVEL_INFO in production, LEVEL_DEBUG in development",
                  "constraint_infos": [
                    {
                      "rule": "assert_enum_defined",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    }
                  ],
                  "enum_values": [
                    {
                      "name": "LEVEL_TRACE",
                      "number": 1,
                      "description": "LEVEL_TRACE is the most verbose log level, used for detailed debugging information"
                    },
                    {
                      "name": "LEVEL_DEBUG",
                      "number": 2,
                      "description": "LEVEL_DEBUG is used for debugging information, less verbose than trace"
                    },
                    {
                      "name": "LEVEL_INFO",
                      "number": 3,
                      "description": "LEVEL_INFO is used for informational messages about normal operations"
                    },
                    {
                      "name": "LEVEL_WARN",
                      "number": 4,
                      "description": "LEVEL_WARN is used for warning messages about potentially problematic situations"
                    },
                    {
                      "name": "LEVEL_ERROR",
                      "number": 5,
                      "description": "LEVEL_ERROR is used for error messages about failures and problems"
                    }
                  ]
                },
                {
                  "name": "development",
                  "type": "bool",
                  "description": "Development enables development mode which:\n   - Uses console format by default\n   - Enables stack traces for warnings and errors\n   - Uses more human-readable timestamps\n Default: false (production mode)"
                },
                {
                  "name": "pretty_print",
                  "type": "bool",
                  "description": "PrettyPrint enables pretty-printed output for JSON format\n This makes JSON logs more readable but increases output size\n Should be disabled in production for performance\n Default: false"
                },
                {
                  "name": "output_paths",
                  "type": "string",
                  "description": "OutputPaths is a list of file paths or URLs to write logs to\n Use \"stdout\" or \"stderr\" for console output\n Example: [\"stdout\", \"/var/log/app.log\"]",
                  "repeated": true,
                  "constraints": [
                    "must be a valid file path (type: PATH_ANY)",
                    "maximum size: 8 elements",
                    "maximum element size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 8,
                      "unit": "elements",
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_file_path",
                      "target": "field",
                      "value_kind": "enum",
                      "enum_value": "PATH_ANY",
                      "source": "annotation"
                    },
                    {
                      "rule": "default_max_element_size",
                      "target": "element",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "error_output_paths",
                  "type": "string",
                  "description": "ErrorOutputPaths is a list of file paths or URLs to write error logs to\n Use \"stderr\" for console error output\n Example: [\"stderr\", \"/var/log/app-errors.log\"]",
                  "repeated": true,
                  "constraints": [
                    "must be a valid file path (type: PATH_ANY)",
                    "maximum size: 8 elements",
                    "maximum element size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 8,
                      "unit": "elements",
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_file_path",
                      "target": "field",
                      "value_kind": "enum",
                      "enum_value": "PATH_ANY",
                      "source": "annotation"
                    },
                    {
                      "rule": "default_max_element_size",
                      "target": "element",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "disable_caller",
                  "type": "bool",
                  "description": "DisableCaller disables automatic inclusion of caller information (file:line) in log entries\n Default: false (caller information is included)"
                },
                {
                  "name": "disable_stacktrace",
                  "type": "bool",
                  "description": "DisableStacktrace disables automatic stacktraces for error-level and above log entries\n Default: false (stacktraces are included for errors)"
                },
                {
                  "name": "initial_fields",
                  "type": "map",
                  "description": "InitialFields is a map of fields to include in every log entry\n Useful for adding context like service name, version, environment, etc.\n Example: {\"service\": \"api\", \"version\": \"1.0.0\", \"environment\": \"production\"}",
                  "repeated": true,
                  "constraints": [
                    "maximum size: 32 entries",
                    "maximum key size: 32768 bytes (default)",
                    "maximum value size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 32,
                      "unit": "entries",
                      "source": "annotation"
                    },
                    {
                      "rule": "default_max_key_size",
                      "target": "key",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    },
                    {
                      "rule": "default_max_value_size",
                      "target": "value",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ],
                  "map_key_type": "string",
                  "map_value_type": "string"
                }
              ]
            }
          },
          {
            "name": "shutdown_timeout_seconds",
            "type": "int64",
            "description": "shutdown_timeout_seconds is the maximum time (in seconds) to wait for graceful\n shutdown after SIGTERM before forcing immediate shutdown.\n Must be positive. Default: 30 seconds.",
            "default": 30,
            "constraints": [
              "duration constraint: DURATION_TYPE_POSITIVE"
            ],
            "constraint_infos": [
              {
                "rule": "assert_duration",
                "target": "field",
                "value_kind": "enum",
                "enum_value": "DURATION_TYPE_POSITIVE",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "max_concurrent_streams",
            "type": "int32",
            "description": "max_concurrent_streams limits the number of concurrent gRPC streams per connection.\n Prevents resource exhaustion from clients opening unlimited streams.\n Default: 100. Set to 0 to use the gRPC library default (unlimited).",
            "default": 100
          },
          {
            "name": "max_send_msg_size",
            "type": "int64",
            "description": "max_send_msg_size is the maximum response message size in bytes.\n Prevents the server from sending responses that could OOM clients.\n Default: 16MB (16777216 bytes). Set to 0 to use the gRPC library default.",
            "default": 16777216
          },
          {
            "name": "keepalive_min_time_seconds",
            "type": "int64",
            "description": "keepalive_min_time_seconds is the minimum interval clients must wait between\n keepalive pings. Clients pinging more frequently are disconnected.\n Default: 30 seconds. Set to 0 to disable enforcement.",
            "default": 30
          },
          {
            "name": "trusted_cas",
            "type": "message",
            "description": "trusted_cas is the explicit list of CA certificates trusted for SPIFFE TLS\n verification when connecting to cluster endpoints. It must not be empty.",
            "repeated": true,
            "constraints": [
              "maximum size: 32 elements"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32,
                "unit": "elements",
                "source": "annotation"
              }
            ],
            "message": {
              "name": "X509Cert",
              "package": "x509",
              "description": "ProtoCert represents an X.509 certificate.\n The certificate is stored as a base64-encoded PEM block.\n Use NewProtoCert() in Go with DER-encoded certificate bytes to create.",
              "fields": [
                {
                  "name": "id",
                  "type": "string",
                  "description": "Id is a unique identifier for the certificate",
                  "constraints": [
                    "maximum size: 256 bytes"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 256,
                      "unit": "bytes",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "base64",
                  "type": "string",
                  "description": "Base64 contains the base64url-encoded PEM certificate block",
                  "required": true,
                  "constraints": [
                    "must be base64 encoded",
                    "maximum size: 16384 bytes"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 16384,
                      "unit": "bytes",
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_base64",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    }
                  ]
                }
              ]
            }
          },
          {
            "name": "spiffe_trust_domain",
            "type": "string",
            "description": "spiffe_trust_domain is the SPIFFE URI authority: a globally unique instance\n name for this autonomous-system instance (need not be a DNS domain).\n It must not contain '/', a scheme, query, or fragment, and carries no path.\n Service identity is built by the generated sys/spiffe helper as:\n   spiffe://\u003cspiffe_trust_domain\u003e/system/\u003clocation_path...\u003e/services/\u003cservice_label\u003e\n If empty, SPIFFE IDs are not set on health reports or X509 URI SANs.",
            "constraints": [
              "maximum size: 256 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 256,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "location_path",
            "type": "string",
            "description": "location_path is this service instance's topology path under /system —\n opaque, tag-delimited, slash-separated segments, arity not fixed\n (e.g. \"aws/123456789012/us-east-1a/cluster-7/team-a\"). Segments follow the\n SPIFFE segment grammar and must not be reserved tags. Supplied by the\n operator/deployment from runtime config (where the service runs); it is\n not a token claim. May be empty (no topology tiers).",
            "constraints": [
              "maximum size: 512 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 512,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "disk_persistence",
            "type": "message",
            "description": "disk_persistence is an init-time/bootstrap setting that enables\n ServiceManager-owned redo-log lifecycle for generated service_store stores.\n When present at ServiceManager creation, the generated ServiceManager opens\n the per-store redo logs, exposes those handles to service code, and owns\n scheduled compaction/roll. It is not hot-reloaded; when absent, typed\n diskstore helpers remain available but no managed roll loop is started.",
            "message": {
              "name": "DiskPersistenceConfig",
              "package": "diskstore",
              "description": "DiskPersistenceConfig configures the SM-managed persistence component that\n automates the redo-log lifecycle (UC2) for service_store-annotated types.\n It is embedded in the ServiceManager config.",
              "fields": [
                {
                  "name": "roll_interval_seconds",
                  "type": "int64",
                  "description": "roll_interval_seconds is the compaction/roll period. Also bounds the\n per-node deterministic roll offset (hash(node-id) % roll_interval).",
                  "default": 86400,
                  "constraints": [
                    "duration constraint: DURATION_TYPE_POSITIVE"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_duration",
                      "target": "field",
                      "value_kind": "enum",
                      "enum_value": "DURATION_TYPE_POSITIVE",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "archive_count",
                  "type": "uint32",
                  "description": "archive_count is how many rolled archive files to retain.",
                  "default": 3
                },
                {
                  "name": "dir",
                  "type": "string",
                  "description": "dir is the base directory (on the service's own volume) for the\n active / building / temp / archive files.",
                  "required": true,
                  "constraints": [
                    "maximum size: 4096 bytes"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 4096,
                      "unit": "bytes",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "file_permission",
                  "type": "message",
                  "description": "file_permission is the Unix permission for the data files (e.g. 0600).",
                  "message": {
                    "name": "Permission",
                    "package": "filesystem",
                    "description": "Permission represents Unix-style file permissions (e.g., 755).\n Each field is a 3-bit mask: read (4) + write (2) + execute (1).",
                    "fields": [
                      {
                        "name": "owner",
                        "type": "uint32",
                        "description": "owner permission bits (0-7)",
                        "constraints": [
                          "must be \u003e= 0",
                          "must be \u003c= 7"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "assert_ge",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 0,
                            "source": "annotation"
                          },
                          {
                            "rule": "assert_le",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 7,
                            "source": "annotation"
                          }
                        ]
                      },
                      {
                        "name": "group",
                        "type": "uint32",
                        "description": "group permission bits (0-7)",
                        "constraints": [
                          "must be \u003e= 0",
                          "must be \u003c= 7"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "assert_ge",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 0,
                            "source": "annotation"
                          },
                          {
                            "rule": "assert_le",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 7,
                            "source": "annotation"
                          }
                        ]
                      },
                      {
                        "name": "other",
                        "type": "uint32",
                        "description": "other permission bits (0-7)",
                        "constraints": [
                          "must be \u003e= 0",
                          "must be \u003c= 7"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "assert_ge",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 0,
                            "source": "annotation"
                          },
                          {
                            "rule": "assert_le",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 7,
                            "source": "annotation"
                          }
                        ]
                      }
                    ]
                  }
                },
                {
                  "name": "compression",
                  "type": "enum",
                  "description": "compression for rolled/archived files + snapshots; the live append tail\n stays uncompressed.",
                  "constraint_infos": [
                    {
                      "rule": "assert_enum_defined",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    }
                  ],
                  "enum_values": [
                    {
                      "name": "COMPRESSION_NONE",
                      "number": 0
                    },
                    {
                      "name": "COMPRESSION_GZ",
                      "number": 1
                    },
                    {
                      "name": "COMPRESSION_BZ",
                      "number": 2
                    }
                  ]
                }
              ]
            }
          },
          {
            "name": "anonymize_hmac_key",
            "type": "bytes",
            "description": "anonymize_hmac_key is the per-deployment data-entitlement ANONYMIZE secret:\n the keyed-HMAC key the generated service wrapper supplies to Sanitize\u003cT\u003e so\n a value pseudonymizes to the same surrogate at any depth, across services\n and restarts. Required only by services whose records carry\n ANONYMIZE-capable (spec.redact) fields — the generated pseudonymize\n primitives fail loud on an empty key.",
            "constraints": [
              "maximum size: 256 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 256,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "health_probe_port",
            "type": "int32",
            "description": "health_probe_port is the port for a separate PLAINTEXT gRPC listener that\n serves ONLY grpc.health.v1. k8s kubelet probes are plaintext-only and\n cannot speak TLS, so the main TLS port (listen_address) is invisible to\n them. This listener runs on a completely separate grpc.Server / tonic\n Server / NettyServerBuilder with no TLS, no auth interceptors, and no\n business services registered — isolation is the security argument.\n The health status reflects the same StatusSink-driven state as the TLS\n health endpoint: NOT_SERVING until bootstrap completes, then tracks\n handler health (UNHEALTHY → NOT_SERVING, recovery → SERVING).\n Default: 8444. Set to 0 to disable the plaintext health probe listener.",
            "default": 8444
          },
          {
            "name": "config_fetch_timeout_seconds",
            "type": "int64",
            "description": "config_fetch_timeout_seconds bounds the generated state-singleton startup\n fetch. A singleton Get can race the state authority's own convergence and\n return a value that has not been fully seeded yet; the generated fetch()\n retries with the watch-restart backoff for as long as the fetched value\n fails its own generated validate\u003cT\u003e, and fails loudly once this budget is\n spent rather than handing the caller a value it already knows is invalid.\n Must be positive. Default: 30 seconds.",
            "default": 30,
            "constraints": [
              "duration constraint: DURATION_TYPE_POSITIVE"
            ],
            "constraint_infos": [
              {
                "rule": "assert_duration",
                "target": "field",
                "value_kind": "enum",
                "enum_value": "DURATION_TYPE_POSITIVE",
                "source": "annotation"
              }
            ]
          }
        ]
      }
    },
    {
      "name": "format",
      "type": "enum",
      "description": "format is the default output format for `cavalier api`.",
      "enum_values": [
        {
          "name": "OUTPUT_FORMAT_JSON",
          "number": 1,
          "description": "JSON format"
        },
        {
          "name": "OUTPUT_FORMAT_YAML",
          "number": 2,
          "description": "YAML format"
        },
        {
          "name": "OUTPUT_FORMAT_MULTI_YAML",
          "number": 3,
          "description": "Multi YAML format (e.g. ---)"
        },
        {
          "name": "OUTPUT_FORMAT_TEXT",
          "number": 4,
          "description": "Plain text format"
        },
        {
          "name": "OUTPUT_FORMAT_ENV_VAR",
          "number": 5,
          "description": "Environment variable format"
        },
        {
          "name": "OUTPUT_FORMAT_PROTO_WIRE",
          "number": 6,
          "description": "Protobuf wire format (binary)"
        },
        {
          "name": "OUTPUT_FORMAT_TOML",
          "number": 7,
          "description": "TOML format"
        }
      ]
    },
    {
      "name": "namespace",
      "type": "string",
      "description": "namespace is a bare project leaf name (e.g. \"default\"), not a namespace\n path. It selects the project at mint time — oauth.SessionRequest carries\n no namespace, tokenrequest.TokenMintRequest.project does. The CLI does no\n domain lookup; the user names the project, and kernel derives the tenant\n from OPA and validates the leaf against authorized_projects.",
      "constraints": [
        "maximum size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
    },
    {
      "name": "api_transport",
      "type": "enum",
      "description": "api_transport selects the gateway transport used by `cavalier api`.\n Defaults to GRPC; REST is intended for testing and troubleshooting.",
      "enum_values": [
        {
          "name": "API_TRANSPORT_GRPC",
          "number": 1
        },
        {
          "name": "API_TRANSPORT_REST",
          "number": 2
        }
      ]
    },
    {
      "name": "trace_id",
      "type": "string",
      "constraints": [
        "maximum size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
    },
    {
      "name": "noop",
      "type": "bool"
    }
  ]
}

fields.description:
InitialFields is a map of fields to include in every log entry
 Useful for adding context like service name, version, environment, etc.
 Example: {"service": "api", "version": "1.0.0", "environment": "production"}

types.schema_json:
{
  "name": "ProfileConfig",
  "package": "schematicctl",
  "description": "ProfileConfig is the top-level format of ~/.cavalier/config.yaml.",
  "fields": [
    {
      "name": "current_profile",
      "type": "string",
      "description": "current_profile is the active profile name.",
      "constraints": [
        "maximum size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
    },
    {
      "name": "profiles",
      "type": "map",
      "description": "profiles is a map of named connection profiles.",
      "repeated": true,
      "constraints": [
        "maximum size: 64 entries",
        "maximum key size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 64,
          "unit": "entries",
          "source": "annotation"
        },
        {
          "rule": "default_max_key_size",
          "target": "key",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ],
      "map_key_type": "string",
      "map_value_type": "Config"
    },
    {
      "name": "trace_id",
      "type": "string",
      "constraints": [
        "maximum size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
    },
    {
      "name": "noop",
      "type": "bool"
    }
  ]
}

{
  "name": "CredPair",
  "package": "credentials",
  "description": "CredPair is a tenant-scoped credential. Public key stored in the tenant's\n KernelTenantConfig slice; private key never leaves the holder. Used to\n authenticate kernel.TenantAdmin RPCs and (downstream) any tenant-scoped\n RPC across the cluster.\n\n A request authenticated by CredPair carries the SPIFFE URI\n `spiffe://\u003cspiffe_prefix\u003e/\u003ctenant_name\u003e/users/cred-pair:\u003cid\u003e`.\n\n `entitlements` must always be a subset of the tenant's ceiling\n (kernel.Constraints.entitlements_ceiling). Enforcement is in\n kernel.TenantAdmin.SetTenantConfig.",
  "fields": [
    {
      "name": "id",
      "type": "string",
      "description": "id is a unique identifier for this cred_pair within its owning tenant.",
      "required": true,
      "constraints": [
        "minimum size: 1",
        "maximum size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "assert_required",
          "target": "field",
          "value_kind": "bool",
          "bool_value": true,
          "source": "annotation"
        },
        {
          "rule": "assert_min_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 1,
          "unit": "bytes",
          "source": "annotation"
        },
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
    },
    {
      "name": "tenant_name",
      "type": "string",
      "description": "tenant_name names the owning tenant — the namespace that `namespaces` are\n relative to. The cluster cred_pair's owner is the root \"/\".",
      "required": true,
      "constraints": [
        "maximum size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "assert_required",
          "target": "field",
          "value_kind": "bool",
          "bool_value": true,
          "source": "annotation"
        },
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
    },
    {
      "name": "public_key",
      "type": "message",
      "description": "public_key is the cred_pair's public key, as a JWK. Mint verifies a\n cred_pair-signed proof against it to issue a token.",
      "required": true,
      "constraint_infos": [
        {
          "rule": "assert_required",
          "target": "field",
          "value_kind": "bool",
          "bool_value": true,
          "source": "annotation"
        }
      ],
      "message": {
        "name": "Jwk",
        "package": "jwk",
        "description": "Jwk represents a JSON Web Key as defined in RFC 7517.\n It contains the public key parameters for RSA (e, n), EC (crv, x, y), or OKP (crv, x) keys.\n JWK is used for key distribution and verification in JSON-based protocols like JWT.",
        "fields": [
          {
            "name": "kty",
            "type": "enum",
            "description": "Kty is the key type parameter (RSA, EC, or OKP)",
            "enum_values": [
              {
                "name": "KEY_TYPE_RSA",
                "number": 1,
                "description": "KeyTypeRsa represents an RSA key type"
              },
              {
                "name": "KEY_TYPE_EC",
                "number": 2,
                "description": "KeyTypeEc represents an Elliptic Curve key type"
              },
              {
                "name": "KEY_TYPE_OKP",
                "number": 3,
                "description": "KeyTypeOkp represents an Octet Key Pair (EdDSA) key type"
              }
            ]
          },
          {
            "name": "alg",
            "type": "string",
            "description": "Alg is the algorithm intended for use with the key (e.g., \"RS384\", \"ES256\", \"EdDSA\")",
            "required": true,
            "constraints": [
              "maximum size: 64 bytes",
              "minimum size: 1"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 64,
                "unit": "bytes",
                "source": "annotation"
              },
              {
                "rule": "assert_min_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 1,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "kid",
            "type": "string",
            "description": "Kid is the key ID used to match keys with signatures",
            "required": true,
            "constraints": [
              "maximum size: 512 bytes",
              "minimum size: 1"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 512,
                "unit": "bytes",
                "source": "annotation"
              },
              {
                "rule": "assert_min_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 1,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "use",
            "type": "enum",
            "description": "Use indicates the intended use of the key (sig for signatures, enc for encryption)",
            "enum_values": [
              {
                "name": "JWK_USE_TYPE_SIG",
                "number": 1,
                "description": "JwkUseTypeSig indicates the key is used for digital signatures"
              },
              {
                "name": "JWK_USE_TYPE_ENC",
                "number": 2,
                "description": "JwkUseTypeEnc indicates the key is used for encryption"
              }
            ]
          },
          {
            "name": "e",
            "type": "string",
            "description": "E is the RSA public exponent (base64url encoded without padding)",
            "constraints": [
              "must be base64 encoded",
              "maximum size: 64 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 64,
                "unit": "bytes",
                "source": "annotation"
              },
              {
                "rule": "assert_base64",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              }
            ]
          },
          {
            "name": "n",
            "type": "string",
            "description": "N is the RSA modulus (base64url encoded without padding)",
            "constraints": [
              "must be base64 encoded",
              "maximum size: 1024 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 1024,
                "unit": "bytes",
                "source": "annotation"
              },
              {
                "rule": "assert_base64",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              }
            ]
          },
          {
            "name": "crv",
            "type": "string",
            "description": "Crv is the elliptic curve name (e.g., P-256, P-384, P-521, Ed25519)",
            "constraints": [
              "maximum size: 64 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 64,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "x",
            "type": "string",
            "description": "X is the x coordinate for EC keys or the public key for OKP (base64url encoded without padding)",
            "constraints": [
              "must be base64 encoded",
              "maximum size: 256 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 256,
                "unit": "bytes",
                "source": "annotation"
              },
              {
                "rule": "assert_base64",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              }
            ]
          },
          {
            "name": "y",
            "type": "string",
            "description": "Y is the y coordinate for EC keys (base64url encoded without padding, not used for OKP)",
            "constraints": [
              "must be base64 encoded",
              "maximum size: 256 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 256,
                "unit": "bytes",
                "source": "annotation"
              },
              {
                "rule": "assert_base64",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              }
            ]
          },
          {
            "name": "exp",
            "type": "int64",
            "description": "Exp is the expiration in epoch seconds. This is not part of the JWK spec as the spec does\n not specify how to handle public key expiration.\n When stored in a collection with epoch_expiration, the state store computes TTL = exp - now\n and auto-evicts the entry on expiry."
          },
          {
            "name": "created",
            "type": "int64",
            "description": "Created is the Unix epoch timestamp (seconds) when the key was created (optional).\n If set, valid range: 1735689600 (2025-01-01) to 8045740800 (2225-01-01)",
            "constraints": [
              "must be \u003e= 1735689600",
              "must be \u003c= 8045740800"
            ],
            "constraint_infos": [
              {
                "rule": "assert_ge",
                "target": "field",
                "value_kind": "int",
                "int_value": 1735689600,
                "source": "annotation"
              },
              {
                "rule": "assert_le",
                "target": "field",
                "value_kind": "int",
                "int_value": 8045740800,
                "source": "annotation"
              }
            ]
          }
        ]
      }
    },
    {
      "name": "entitlements",
      "type": "message",
      "description": "entitlements this cred_pair holds (⊆ the owning tenant's ceiling), as the\n SAME TokenEntitlements the C2S authorizer checks: the minted cred_pair token\n sets service_entitlements = this directly (uniform with IDP-user tokens).",
      "message": {
        "name": "TokenEntitlements",
        "package": "entitlements",
        "description": "TokenEntitlements holds compressed C2S entitlements embedded in user tokens.\n OPA returns this structure directly; the token authority embeds it in the JWT service_entitlements claim.\n grants may contain exact or wildcard grant tokens; generated helpers normalize them before authorization.",
        "fields": [
          {
