      "message": {
        "name": "Config",
        "package": "operator",
        "description": "OperatorConfig is the top-level operator configuration.\n\n Lifecycle:\n   1. operator init ca                   — generate root CA → crypto.yaml\n   2. operator init cluster --ca \u003cpath\u003e  — generate cluster PKI + write operator.yaml\n   3. operator                           — run (IN_CLUSTER) or generate charts (GENERATE_ONLY)\n\n When deployed to Kubernetes:\n   operator.yaml  → ConfigMap  (schematic-operator-config)\n   crypto.yaml    → Secret     (schematic-operator-crypto)\n Both are mounted and merged by the operator at startup.",
        "fields": [
          {
            "name": "mode",
            "type": "enum",
            "description": "How the operator runs.",
            "enum_values": [
              {
                "name": "IN_CLUSTER",
                "number": 0,
                "description": "IN_CLUSTER is the default: the operator runs inside Kubernetes and\n continuously reconciles the desired cluster state by managing Helm releases.\n gateway_nodes is automatically set to the number of schedulable nodes."
              },
              {
                "name": "GENERATE_ONLY",
                "number": 1,
                "description": "GENERATE_ONLY: one-shot CLI mode. Generates Helm charts, writes them to\n output_dir, and exits. Does not communicate with the Kubernetes API."
              }
            ]
          },
          {
            "name": "fqdn",
            "type": "string",
            "description": "Public FQDN for the cluster (e.g. \"api.example.com\").",
            "constraints": [
              "maximum size: 32768 bytes (default)"
