          "target": "field",
          "value_kind": "int",
          "int_value": 0,
          "source": "annotation"
        }
      ]
    },
    {
      "name": "owner_principal",
      "type": "string",
      "required": true,
      "constraints": [
        "maximum size: 256 bytes"
      ],
      "constraint_infos": [
        {
          "rule": "assert_required",
          "target": "field",
          "value_kind": "bool",
          "bool_value": true,
          "source": "annotation"
        },
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 256,
          "unit": "bytes",
          "source": "annotation"
        }
      ],
      "filter_mode": "eq",
      "store_principal": true
    },
    {
      "name": "deleted",
      "type": "bool"
    },
    {
      "name": "spiffe_id",
      "type": "string",
      "constraints": [
        "maximum size: 1024 bytes"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 1024,
          "unit": "bytes",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "namespace",
      "type": "string",
      "required": true,
      "constraints": [
        "maximum size: 256 bytes"
      ],
      "constraint_infos": [
        {
          "rule": "assert_required",
          "target": "field",
          "value_kind": "bool",
          "bool_value": true,
          "source": "annotation"
        },
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 256,
          "unit": "bytes",
          "source": "annotation"
        }
      ],
      "filter_mode": "eq",
      "store_namespace": true
    },
    {
      "name": "trace_id",
      "type": "string",
      "constraints": [
        "maximum size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
    },
    {
      "name": "noop",
      "type": "bool"
    }
  ]
}

