          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 64,
          "unit": "bytes",
          "source": "annotation"
        }
      ],
      "filter_mode": "eq"
    },
    {
      "name": "content_hash",
      "type": "string",
      "required": true,
      "constraints": [
        "maximum size: 64 bytes",
        "minimum size: 64"
      ],
      "constraint_infos": [
        {
          "rule": "assert_required",
          "target": "field",
          "value_kind": "bool",
          "bool_value": true,
          "source": "annotation"
        },
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 64,
          "unit": "bytes",
          "source": "annotation"
        },
        {
          "rule": "assert_min_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 64,
          "unit": "bytes",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "size_bytes",
      "type": "int64",
      "constraints": [
        "must be \u003e= 0"
      ],
      "constraint_infos": [
        {
          "rule": "assert_ge",
          "target": "field",
          "value_kind": "int",
          "int_value": 0,
          "source": "annotation"
        }
      ]
    },
    {
      "name": "content_type",
      "type": "string",
      "required": true,
      "constraints": [
        "maximum size: 128 bytes"
      ],
      "constraint_infos": [
        {
          "rule": "assert_required",
          "target": "field",
          "value_kind": "bool",
          "bool_value": true,
          "source": "annotation"
        },
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 128,
          "unit": "bytes",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "reserved_bytes",
      "type": "int64",
      "description": "reserved_bytes is what this session holds against the tenant's group quota\n while it is PENDING. It is the DECLARED size — the only number available\n before the bytes arrive — which is why `max_blob_bytes` is also enforced on\n the wire: the reservation is a promise the stream still has to keep.",
      "constraints": [
