{
  "name": "VolumeGroup",
  "package": "blobstore",
  "description": "VolumeGroup is one group's rules, as this service receives them.\n\n IT IS NOT DECLARED HERE. A group is declared at BUILD TIME by the consuming\n service — DocManager declares `documents`, a later feature declares `photos`\n — through the `(spec.volume_group)` service-level annotation tacplus surfaces\n in registry.json, and the operator renders every declared group into this\n config (R4, and the doc's Work split: the annotation is tacplus's slice, the\n rendering is the operator's). This message is the RECEIVING end of that\n pipeline and nothing more.\n\n So the list below being EMPTY is the correct state of a cluster whose\n services have declared no groups: every upload is then refused, which is what\n \"no group, no upload\" means. It is not a reason to invent a default group.",
  "fields": [
    {
      "name": "name",
      "type": "string",
      "description": "name is the group's identity, and the first path segment of every file it\n holds (`\u003cgroup\u003e/\u003cns\u003e/\u003csha256\u003e`). Unique across the fleet — tacplus refuses\n a duplicate at generation, so this service does not have to arbitrate.",
      "required": true,
      "constraints": [
        "maximum size: 64 bytes",
        "minimum size: 1"
      ],
      "constraint_infos": [
        {
          "rule": "assert_required",
          "target": "field",
          "value_kind": "bool",
          "bool_value": true,
          "source": "annotation"
        },
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 64,
          "unit": "bytes",
          "source": "annotation"
        },
        {
          "rule": "assert_min_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 1,
          "unit": "bytes",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "max_blob_bytes",
      "type": "int64",
      "description": "max_blob_bytes is the largest single blob the group accepts. Enforced ON\n THE WIRE, not from the declared size: an upload is aborted the moment the\n stream passes it (R9 step 2), because a client that lied about `size_bytes`\n must not be able to fill the disk before the check.",
      "required": true,
      "constraints": [
        "must be \u003e 0"
      ],
      "constraint_infos": [
        {
          "rule": "assert_required",
          "target": "field",
          "value_kind": "bool",
          "bool_value": true,
          "source": "annotation"
        },
        {
          "rule": "assert_gt",
          "target": "field",
          "value_kind": "int",
          "int_value": 0,
          "source": "annotation"
        }
      ]
    },
    {
      "name": "content_types",
      "type": "string",
      "description": "content_types is the exhaustive allow-list. A type not listed is refused at\n CreateUpload, and the bytes are sniffed again at finish (R4) — a renamed\n `.exe` declaring `application/pdf` fails on its magic bytes even though it\n passed this list.",
      "required": true,
      "repeated": true,
      "constraints": [
        "maximum size: 64 elements",
        "maximum element size: 128 bytes"
      ],
      "constraint_infos": [
        {
          "rule": "assert_required",
          "target": "field",
          "value_kind": "bool",
          "bool_value": true,
          "source": "annotation"
        },
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 64,
          "unit": "elements",
          "source": "annotation"
        },
        {
          "rule": "assert_element_max_size",
          "target": "element",
          "value_kind": "int",
          "int_value": 128,
          "unit": "bytes",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "tenant_quota_bytes",
      "type": "int64",
      "description": "tenant_quota_bytes is the ceiling on the SUM of promoted blob sizes for one\n tenant in this group. Quotas hang off the group and there is no separate\n global tenant quota (R4).",
      "required": true,
      "constraints": [
        "must be \u003e 0"
