              {
                "name": "INGEST_STAGE_RECEIVED",
                "number": 1
              },
              {
                "name": "INGEST_STAGE_OCR",
                "number": 2
              },
              {
                "name": "INGEST_STAGE_COMPRESSION",
                "number": 3
              },
              {
                "name": "INGEST_STAGE_HASHING",
                "number": 4
              },
              {
                "name": "INGEST_STAGE_FILED",
                "number": 5
              },
              {
                "name": "INGEST_STAGE_FAILED",
                "number": 6
              }
