{
  "name": "Config",
  "package": "kernel",
  "description": "Config is the complete configuration for a Kernel node.\n Schematic assembles this config and delivers it as a single file.\n Kernel reads the file at boot. Hot-reloadable fields (delegates,\n entitlements, rate limits, token lifetimes) can be updated by\n re-reading the file on signal; topology and TLS changes require restart.",
  "fields": [
    {
      "name": "cluster_name",
      "type": "string",
      "description": "cluster_name is the logical name for this cluster.\n All nodes in the same cluster must use the same name.",
      "required": true,
      "constraints": [
        "maximum size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "assert_required",
