      "name": "people_idp_credentials",
      "type": "message",
      "description": "people_idp_credentials are the OAuth client credentials for the RESERVED\n `people` tenant's two fixed identity providers (Sign in with Apple, Google\n Sign-In). Kernel seeds them into /tenants/people's TenantConfig.oauth at\n every boot, exactly as root_cred_pairs are seeded into the root namespace.\n\n Only the client credentials are configurable: each entry names a provider\n from the closed PeopleIdpProvider enum and kernel supplies the issuer URL\n from its own fixed table. \"The `people` tenant's IdP set is fixed\" is\n therefore a property of this type, not of an operator's discipline — there\n is no field a deployment could point at a third issuer.",
      "repeated": true,
      "constraints": [
        "maximum size: 2 elements"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 2,
          "unit": "elements",
          "source": "annotation"
        }
      ],
      "message": {
        "name": "PeopleIdpCredential",
        "package": "kernel",
        "description": "PeopleIdpCredential is one provider's OAuth client credentials, the only part\n of the `people` tenant's IdP configuration a deployment supplies. Kernel adds\n the issuer URL from its fixed table and writes the pair into\n /tenants/people's oauth.OAuthTenantConfig, so oauth reads the `people`\n tenant's providers through the same per-tenant config slice every other\n tenant uses.",
        "fields": [
          {
            "name": "provider",
            "type": "enum",
            "constraint_infos": [
              {
                "rule": "assert_enum_defined",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              }
            ],
            "enum_values": [
              {
                "name": "PEOPLE_IDP_PROVIDER_APPLE",
                "number": 1,
                "description": "Sign in with Apple (issuer https://appleid.apple.com)."
              },
              {
                "name": "PEOPLE_IDP_PROVIDER_GOOGLE",
                "number": 2,
                "description": "Google Sign-In (issuer https://accounts.google.com)."
              }
            ]
          },
          {
            "name": "client_id",
            "type": "string",
            "description": "client_id is the OAuth2 client identifier registered with the provider.",
            "required": true,
            "constraints": [
              "minimum size: 1",
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_min_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 1,
                "unit": "bytes",
                "source": "annotation"
              },
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "client_secret",
            "type": "string",
            "description": "client_secret is the OAuth2 client secret; comes from the secrets overlay.",
            "required": true,
            "constraints": [
              "minimum size: 1",
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_min_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 1,
                "unit": "bytes",
                "source": "annotation"
              },
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "trace_id",
            "type": "string",
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "noop",
            "type": "bool"
          }
        ]
      }
    },
    {
      "name": "trace_id",
      "type": "string",
      "constraints": [
        "maximum size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
    },
    {
      "name": "noop",
      "type": "bool"
    }
  ]
}

fields.description:
InitialFields is a map of fields to include in every log entry
 Useful for adding context like service name, version, environment, etc.
 Example: {"service": "api", "version": "1.0.0", "environment": "production"}

types.schema_json:
{
  "name": "ConfigState",
  "package": "kernel",
  "description": "ConfigState is the kernel-hosted persistence boundary for tenants/projects.\n Kernel writes it and persists it; other services watch their per-tenant/\n per-project config slice via the export: true wire.",
  "fields": [
    {
      "name": "tenants",
      "type": "message",
      "description": "tenants is the list of all tenant records, keyed by tenant.name.",
      "repeated": true,
      "constraints": [
        "maximum size: 4096 elements"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 4096,
          "unit": "elements",
          "source": "annotation"
        }
      ],
      "message": {
        "name": "Tenant",
        "package": "kernel",
        "description": "Tenant is the core identity record for a tenant in the cluster.\n `name` is unique, immutable, and becomes the tenant's SPIFFE segment:\n   spiffe://\u003ctrust-domain\u003e/tenants/\u003cname\u003e/...",
        "fields": [
          {
            "name": "name",
            "type": "string",
            "required": true,
            "constraints": [
              "maximum size: 128 bytes",
              "minimum size: 1"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 128,
                "unit": "bytes",
                "source": "annotation"
              },
              {
                "rule": "assert_min_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 1,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "status",
            "type": "enum",
            "enum_values": [
              {
                "name": "TENANT_STATUS_ACTIVE",
                "number": 1
              },
              {
                "name": "TENANT_STATUS_SUSPENDED",
                "number": 2
              }
            ]
          },
          {
            "name": "constraints",
            "type": "message",
            "description": "constraints is the ancestor-set limits (entitlements ceiling now; domain\n later). Set at creation; mutable only by an ancestor.",
            "message": {
              "name": "Constraints",
              "package": "kernel",
              "description": "Constraints are the limits an ancestor places on a tenant. They live on the\n Tenant record (set at CreateTenant), are mutable only by an ancestor, and are\n immutable to the tenant itself — so the tenant genuinely cannot raise its own\n limits. Validated on CreateTenant and SetTenantConfig.\n\n (The \"min-admin-credential\" rule — config must always contain \u003e=1 cred_pair\n entitled to administer the tenant — is NOT a field here: it is an always-on\n invariant enforced in the SetTenantConfig validation path, satisfiable by\n create-and-discard. It is not an ancestor toggle.)",
              "fields": [
                {
                  "name": "entitlements_ceiling",
                  "type": "message",
                  "description": "entitlements_ceiling is the maximum set of entitlements anyone inside this\n tenant may ever hold. Every cred_pair's entitlements ⊆ this; a sub-tenant's\n ceiling ⊆ this. Replaces the former standalone Tenant.entitlements field.",
                  "message": {
                    "name": "TokenEntitlements",
                    "package": "entitlements",
                    "description": "TokenEntitlements holds compressed C2S entitlements embedded in user tokens.\n OPA returns this structure directly; the token authority embeds it in the JWT service_entitlements claim.\n grants may contain exact or wildcard grant tokens; generated helpers normalize them before authorization.",
                    "fields": [
                      {
                        "name": "grants",
                        "type": "string",
                        "description": "grants is a flat list of generated grant tokens, e.g. PACKAGE_SERVICE_RPC.",
                        "repeated": true,
                        "constraints": [
                          "maximum size: 1024 elements (default)",
                          "maximum element size: 32768 bytes (default)"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "default_max_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 1024,
                            "defaulted": true,
                            "unit": "elements",
                            "source": "default_bound"
                          },
                          {
                            "rule": "default_max_element_size",
                            "target": "element",
                            "value_kind": "int",
                            "int_value": 32768,
                            "defaulted": true,
                            "unit": "bytes",
                            "source": "default_bound"
                          }
                        ]
                      },
                      {
                        "name": "data_grants",
                        "type": "string",
                        "description": "data_grants is a flat list of generated data-entitlement grant tokens, e.g.\n PACKAGE_RECORD_FIELD. A data grant names what the caller may SEE RAW: a MAY_*\n redact field with a matching grant egresses raw; absent a grant the field gets\n its most-protective default (MAY_REDACT -\u003e REDACT, MAY_ANONYMIZE -\u003e ANONYMIZE).\n Stamped by OPA at token-exchange time alongside grants — an identity property,\n never a request parameter.",
                        "repeated": true,
                        "constraints": [
                          "maximum size: 1024 elements (default)",
                          "maximum element size: 32768 bytes (default)"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "default_max_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 1024,
                            "defaulted": true,
                            "unit": "elements",
                            "source": "default_bound"
                          },
                          {
                            "rule": "default_max_element_size",
                            "target": "element",
                            "value_kind": "int",
                            "int_value": 32768,
                            "defaulted": true,
                            "unit": "bytes",
                            "source": "default_bound"
                          }
                        ]
                      },
                      {
                        "name": "principal_scope",
                        "type": "string",
                        "description": "principal_scope is how wide the caller's authority over PRINCIPALS is, as a\n spec.PrincipalScope enum VALUE NAME (e.g. \"PRINCIPAL_SCOPE_ANY\"). It is the\n claim the generated (spec.owner_default) guard reads to tell an owner acting\n on its own row from a principal whose authority is wider than itself.\n Absent, empty, PRINCIPAL_SCOPE_UNSPECIFIED and PRINCIPAL_SCOPE_SELF_ONLY all\n mean self-scoped: the guard fails closed, so a policy that stamps nothing\n leaves every caller exactly as narrow as it is today.\n Stamped by OPA at token-exchange time alongside grants — an identity\n property, never a request parameter.",
                        "constraints": [
                          "maximum size: 32768 bytes (default)"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "default_max_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 32768,
                            "defaulted": true,
                            "unit": "bytes",
                            "source": "default_bound"
                          }
                        ]
                      },
                      {
                        "name": "azp",
                        "type": "string",
                        "description": "azp restricts these entitlements to tokens with a matching authorized party.\n Empty = entitlements apply regardless of azp.",
                        "repeated": true,
                        "constraints": [
                          "maximum size: 1024 elements (default)",
                          "maximum element size: 32768 bytes (default)"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "default_max_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 1024,
                            "defaulted": true,
                            "unit": "elements",
                            "source": "default_bound"
                          },
                          {
                            "rule": "default_max_element_size",
                            "target": "element",
                            "value_kind": "int",
                            "int_value": 32768,
                            "defaulted": true,
                            "unit": "bytes",
                            "source": "default_bound"
                          }
                        ]
                      }
                    ]
                  }
                },
                {
                  "name": "trace_id",
                  "type": "string",
                  "constraints": [
                    "maximum size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "default_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "noop",
                  "type": "bool"
                }
              ]
            }
          },
          {
            "name": "created_at",
            "type": "message"
          },
          {
            "name": "updated_at",
            "type": "message"
          },
          {
            "name": "trace_id",
            "type": "string",
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "noop",
            "type": "bool"
          }
        ]
      }
    },
    {
      "name": "tenant_configs",
      "type": "message",
      "description": "tenant_configs stores each tenant's TenantConfig, keyed by tenant_name.",
      "repeated": true,
      "constraints": [
        "maximum size: 4096 elements"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 4096,
          "unit": "elements",
          "source": "annotation"
        }
      ],
      "message": {
        "name": "TenantConfigEntry",
        "package": "kernel",
        "description": "TenantConfigEntry maps a tenant_name to its full TenantConfig (the tacplus\n config slices: kernel cred_pairs, oauth IDP, opa policy). TenantAdmin RPCs\n write these.",
        "fields": [
          {
            "name": "tenant_name",
            "type": "string",
            "required": true,
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "config",
            "type": "message",
            "message": {
              "name": "TenantConfig",
              "package": "tenant_config",
              "description": "TenantConfig aggregates per-service tenant configuration slices.\n Field names match service names; field numbers are stable via registry.yaml.",
              "fields": [
                {
                  "name": "kernel",
                  "type": "message",
                  "message": {
                    "name": "KernelTenantConfig",
                    "package": "credentials",
                    "description": "KernelTenantConfig is the per-tenant kernel configuration slice.\n Tacplus auto-generates TenantConfig with this as the kernel field.",
                    "fields": [
                      {
                        "name": "cred_pairs",
                        "type": "message",
                        "description": "cred_pairs are the tenant's cred_pairs (JWK + entitlements + tenant-relative\n namespaces). They authenticate management RPCs as ordinary C2S identities\n (no P2S). Public keys only — private keys never enter the cluster. The\n creating root registers the tenant's first cred_pair public key via\n kernel.TenantAdmin.SetTenantConfig (bootstrap); nothing is minted or\n delivered server-side. Holders generate their own keypairs off-cluster.",
                        "repeated": true,
                        "constraints": [
                          "maximum size: 256 elements"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "assert_max_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 256,
                            "unit": "elements",
                            "source": "annotation"
                          }
                        ],
                        "message": {
                          "name": "CredPair",
                          "package": "credentials",
                          "description": "CredPair is a tenant-scoped credential. Public key stored in the tenant's\n KernelTenantConfig slice; private key never leaves the holder. Used to\n authenticate kernel.TenantAdmin RPCs and (downstream) any tenant-scoped\n RPC across the cluster.\n\n A request authenticated by CredPair carries the SPIFFE URI\n `spiffe://\u003cspiffe_prefix\u003e/\u003ctenant_name\u003e/users/cred-pair:\u003cid\u003e`.\n\n `entitlements` must always be a subset of the tenant's ceiling\n (kernel.Constraints.entitlements_ceiling). Enforcement is in\n kernel.TenantAdmin.SetTenantConfig.",
                          "fields": [
                            {
                              "name": "id",
                              "type": "string",
                              "description": "id is a unique identifier for this cred_pair within its owning tenant.",
                              "required": true,
                              "constraints": [
                                "minimum size: 1",
                                "maximum size: 32768 bytes (default)"
                              ],
                              "constraint_infos": [
                                {
                                  "rule": "assert_required",
                                  "target": "field",
                                  "value_kind": "bool",
                                  "bool_value": true,
                                  "source": "annotation"
                                },
                                {
                                  "rule": "assert_min_size",
                                  "target": "field",
                                  "value_kind": "int",
                                  "int_value": 1,
                                  "unit": "bytes",
                                  "source": "annotation"
                                },
                                {
                                  "rule": "default_max_size",
                                  "target": "field",
                                  "value_kind": "int",
                                  "int_value": 32768,
                                  "defaulted": true,
                                  "unit": "bytes",
                                  "source": "default_bound"
                                }
                              ]
                            },
                            {
                              "name": "tenant_name",
                              "type": "string",
                              "description": "tenant_name names the owning tenant — the namespace that `namespaces` are\n relative to. The cluster cred_pair's owner is the root \"/\".",
                              "required": true,
                              "constraints": [
                                "maximum size: 32768 bytes (default)"
                              ],
                              "constraint_infos": [
                                {
                                  "rule": "assert_required",
                                  "target": "field",
                                  "value_kind": "bool",
                                  "bool_value": true,
                                  "source": "annotation"
                                },
                                {
                                  "rule": "default_max_size",
                                  "target": "field",
                                  "value_kind": "int",
                                  "int_value": 32768,
                                  "defaulted": true,
                                  "unit": "bytes",
                                  "source": "default_bound"
                                }
                              ]
                            },
                            {
                              "name": "public_key",
                              "type": "message",
                              "description": "public_key is the cred_pair's public key, as a JWK. Mint verifies a\n cred_pair-signed proof against it to issue a token.",
                              "required": true,
                              "constraint_infos": [
                                {
                                  "rule": "assert_required",
                                  "target": "field",
                                  "value_kind": "bool",
                                  "bool_value": true,
                                  "source": "annotation"
                                }
                              ],
                              "message": {
                                "name": "Jwk",
                                "package": "jwk",
                                "description": "Jwk represents a JSON Web Key as defined in RFC 7517.\n It contains the public key parameters for RSA (e, n), EC (crv, x, y), or OKP (crv, x) keys.\n JWK is used for key distribution and verification in JSON-based protocols like JWT.",
                                "fields": [
                                  {
                                    "name": "kty",
                                    "type": "enum",
                                    "description": "Kty is the key type parameter (RSA, EC, or OKP)",
                                    "enum_values": [
                                      {
                                        "name": "KEY_TYPE_RSA",
                                        "number": 1,
                                        "description": "KeyTypeRsa represents an RSA key type"
                                      },
                                      {
                                        "name": "KEY_TYPE_EC",
                                        "number": 2,
                                        "description": "KeyTypeEc represents an Elliptic Curve key type"
                                      },
                                      {
                                        "name": "KEY_TYPE_OKP",
                                        "number": 3,
                                        "description": "KeyTypeOkp represents an Octet Key Pair (EdDSA) key type"
                                      }
                                    ]
                                  },
                                  {
                                    "name": "alg",
                                    "type": "string",
                                    "description": "Alg is the algorithm intended for use with the key (e.g., \"RS384\", \"ES256\", \"EdDSA\")",
                                    "required": true,
                                    "constraints": [
                                      "maximum size: 64 bytes",
                                      "minimum size: 1"
                                    ],
                                    "constraint_infos": [
                                      {
                                        "rule": "assert_required",
                                        "target": "field",
                                        "value_kind": "bool",
                                        "bool_value": true,
                                        "source": "annotation"
                                      },
                                      {
                                        "rule": "assert_max_size",
                                        "target": "field",
                                        "value_kind": "int",
                                        "int_value": 64,
                                        "unit": "bytes",
                                        "source": "annotation"
                                      },
                                      {
                                        "rule": "assert_min_size",
                                        "target": "field",
                                        "value_kind": "int",
                                        "int_value": 1,
                                        "unit": "bytes",
                                        "source": "annotation"
                                      }
                                    ]
                                  },
                                  {
                                    "name": "kid",
                                    "type": "string",
                                    "description": "Kid is the key ID used to match keys with signatures",
                                    "required": true,
                                    "constraints": [
                                      "maximum size: 512 bytes",
                                      "minimum size: 1"
                                    ],
                                    "constraint_infos": [
                                      {
                                        "rule": "assert_required",
                                        "target": "field",
                                        "value_kind": "bool",
                                        "bool_value": true,
                                        "source": "annotation"
                                      },
                                      {
                                        "rule": "assert_max_size",
                                        "target": "field",
                                        "value_kind": "int",
                                        "int_value": 512,
                                        "unit": "bytes",
                                        "source": "annotation"
                                      },
                                      {
                                        "rule": "assert_min_size",
                                        "target": "field",
                                        "value_kind": "int",
                                        "int_value": 1,
                                        "unit": "bytes",
                                        "source": "annotation"
                                      }
                                    ]
                                  },
                                  {
                                    "name": "use",
                                    "type": "enum",
                                    "description": "Use indicates the intended use of the key (sig for signatures, enc for encryption)",
                                    "enum_values": [
                                      {
                                        "name": "JWK_USE_TYPE_SIG",
                                        "number": 1,
                                        "description": "JwkUseTypeSig indicates the key is used for digital signatures"
                                      },
                                      {
                                        "name": "JWK_USE_TYPE_ENC",
                                        "number": 2,
                                        "description": "JwkUseTypeEnc indicates the key is used for encryption"
                                      }
                                    ]
                                  },
                                  {
                                    "name": "e",
                                    "type": "string",
                                    "description": "E is the RSA public exponent (base64url encoded without padding)",
                                    "constraints": [
                                      "must be base64 encoded",
                                      "maximum size: 64 bytes"
                                    ],
                                    "constraint_infos": [
                                      {
                                        "rule": "assert_max_size",
                                        "target": "field",
                                        "value_kind": "int",
                                        "int_value": 64,
                                        "unit": "bytes",
                                        "source": "annotation"
                                      },
                                      {
                                        "rule": "assert_base64",
                                        "target": "field",
                                        "value_kind": "bool",
                                        "bool_value": true,
                                        "source": "annotation"
                                      }
                                    ]
                                  },
                                  {
                                    "name": "n",
                                    "type": "string",
                                    "description": "N is the RSA modulus (base64url encoded without padding)",
                                    "constraints": [
