{
  "name": "CreatePersonalPrincipalRequest",
  "package": "kernel",
  "description": "CreatePersonalPrincipalRequest is a first-launch device registration. It\n carries its own proof: proof_token is a JWT signed by the private half of\n public_key, and the proof's kid becomes the new credential's credential_id.\n The kid is the only source for it, so there is no second field that can\n disagree with what was actually signed.",
  "fields": [
    {
      "name": "proof_token",
      "type": "string",
      "description": "proof_token is the self-signed JWT, the same shape as\n MintClientTokenRequest.input_token.",
      "required": true,
      "constraints": [
        "maximum size: 8192 bytes"
      ],
      "constraint_infos": [
        {
          "rule": "assert_required",
          "target": "field",
          "value_kind": "bool",
          "bool_value": true,
          "source": "annotation"
        },
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 8192,
          "unit": "bytes",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "public_key",
      "type": "message",
      "description": "public_key is the public half of the key that signed proof_token, and is\n stored verbatim as the new PersonalCredential.public_key. Kernel verifies\n the proof against THIS key — a proof that does not verify registers\n nothing.",
      "required": true,
      "constraint_infos": [
        {
          "rule": "assert_required",
          "target": "field",
          "value_kind": "bool",
          "bool_value": true,
          "source": "annotation"
        }
      ],
      "message": {
        "name": "Jwk",
        "package": "jwk",
        "description": "Jwk represents a JSON Web Key as defined in RFC 7517.\n It contains the public key parameters for RSA (e, n), EC (crv, x, y), or OKP (crv, x) keys.\n JWK is used for key distribution and verification in JSON-based protocols like JWT.",
        "fields": [
          {
            "name": "kty",
            "type": "enum",
            "description": "Kty is the key type parameter (RSA, EC, or OKP)",
            "enum_values": [
              {
                "name": "KEY_TYPE_RSA",
                "number": 1,
                "description": "KeyTypeRsa represents an RSA key type"
              },
              {
                "name": "KEY_TYPE_EC",
                "number": 2,
                "description": "KeyTypeEc represents an Elliptic Curve key type"
              },
              {
                "name": "KEY_TYPE_OKP",
                "number": 3,
                "description": "KeyTypeOkp represents an Octet Key Pair (EdDSA) key type"
              }
            ]
          },
          {
            "name": "alg",
            "type": "string",
            "description": "Alg is the algorithm intended for use with the key (e.g., \"RS384\", \"ES256\", \"EdDSA\")",
            "required": true,
            "constraints": [
              "maximum size: 64 bytes",
              "minimum size: 1"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 64,
                "unit": "bytes",
                "source": "annotation"
              },
              {
                "rule": "assert_min_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 1,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "kid",
            "type": "string",
            "description": "Kid is the key ID used to match keys with signatures",
            "required": true,
            "constraints": [
              "maximum size: 512 bytes",
              "minimum size: 1"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
