{
  "name": "Identity",
  "package": "kernel",
  "description": "Identity holds the public verifying keys for kernel's token exchange service.\n Kernel is the sole token authority — all tokens (S2S, U2S, refresh) and\n X.509 certificates are signed by kernel's keys.\n\n Token exchange handles:\n   1. Direct exchange: delegate presents cred_pair JWT or cloud proof → token/cert\n   2. Delegation: broker (oauth, K8S) authenticates via header, mints on behalf\n\n Access: RW for kernel, RO for every service that declares a\n (spec.state_imports) of kernel.Identity. Enforced at run time by the\n generated SecurityAuthenticator.checkAccess on every state RPC — services\n that only need to verify tokens read the public JWKS view instead.",
  "fields": [
    {
      "name": "verifying_keys",
      "type": "message",
      "description": "Verification keys — kernel's public keys, rotated periodically.\n Kernel holds the corresponding private keys internally.\n Used by SecurityInterceptor to validate tokens for cluster calls.\n Sized for the real fleet, not for one node: kernel keeps one active\n signing key per algorithm PER REPLICA (private keys live in each node's\n own disk snapshot and are never shared), and a rotated public key is\n retained for max_token_lifetime_seconds so the tokens it signed stay\n verifiable. With the shipped defaults that is\n   replicas(3) x algorithms(2) x (2592000s retention / 86400s rotation + 1)\n     = 3 x 2 x 31 = 186 keys.\n The cap is 128 rather than 186 because this set is published as a\n jwk.Jwks, whose keys field is capped at 128 by the shared, do-not-modify\n sys/jwk.proto; KeyRotator.MAX_VERIFYING_KEYS enforces the same 128 at run\n time and evicts oldest-first when the set would exceed it. The old 16 was\n sized for a single node and could not hold even a healthy 3-replica set.",
      "repeated": true,
      "constraints": [
        "maximum size: 128 elements"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 128,
          "unit": "elements",
          "source": "annotation"
        }
      ],
      "message": {
        "name": "Jwk",
        "package": "jwk",
        "description": "Jwk represents a JSON Web Key as defined in RFC 7517.\n It contains the public key parameters for RSA (e, n), EC (crv, x, y), or OKP (crv, x) keys.\n JWK is used for key distribution and verification in JSON-based protocols like JWT.",
        "fields": [
          {
            "name": "kty",
            "type": "enum",
            "description": "Kty is the key type parameter (RSA, EC, or OKP)",
            "enum_values": [
              {
                "name": "KEY_TYPE_RSA",
                "number": 1,
                "description": "KeyTypeRsa represents an RSA key type"
              },
              {
                "name": "KEY_TYPE_EC",
                "number": 2,
                "description": "KeyTypeEc represents an Elliptic Curve key type"
              },
              {
                "name": "KEY_TYPE_OKP",
                "number": 3,
                "description": "KeyTypeOkp represents an Octet Key Pair (EdDSA) key type"
              }
            ]
          },
          {
            "name": "alg",
            "type": "string",
            "description": "Alg is the algorithm intended for use with the key (e.g., \"RS384\", \"ES256\", \"EdDSA\")",
            "required": true,
            "constraints": [
              "maximum size: 64 bytes",
              "minimum size: 1"
            ],
            "constraint_infos": [
