{
  "name": "PendingApprovalsQueryResponse",
  "package": "kernel",
  "fields": [
    {
      "name": "results",
      "type": "message",
      "repeated": true,
      "constraints": [
        "maximum size: 1024 elements (default)"
      ],
      "constraint_infos": [
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 1024,
          "defaulted": true,
          "unit": "elements",
          "source": "default_bound"
        }
      ],
      "message": {
        "name": "PendingApproval",
        "package": "kernel",
        "description": "PendingApproval is the platform's one approval primitive: who, which RPC, a\n hash of the exact request, and an expiry.\n\n It exists because \"the token is the user\" is not enough for an RPC that is an\n APPROVAL. A browser IdP session or a delegated agent token can BE the user\n without a human touching hardware, so an approval needs a proof no session\n and no delegate can produce: a signature by a key linked to that person's\n devices. The record is what that signature is verified AGAINST, which is what\n lets the generated (spec.rpc).requires_device check say WHAT was approved and\n not merely that somebody tapped something.\n\n It lives in kernel, beside Person and TenantUserLink, because it is identity:\n the proof that one human, holding one device, consented to one call. It is\n generated against and never reimplemented per product.\n\n NOT SNAPSHOTTED TO DISK, and no (spec.persistence) — the one collection in\n PrincipalState that is deliberately ephemeral. KernelDiskState's own rule is\n that only state which must survive a restart is persisted; an approval lives\n for minutes, and losing one fails CLOSED (the id is simply not found) with\n the person proposing again at the cost of one more tap. TenantUserLink is\n snapshotted precisely because losing IT fails silently instead.",
        "fields": [
          {
            "name": "approval_id",
            "type": "string",
            "description": "approval_id is kernel-minted and opaque. Never derived from the request: two\n people proposing the same call must not collide, and a derivable id would\n let anyone name somebody else's pending approval.",
            "required": true,
            "constraints": [
              "maximum size: 128 bytes",
              "minimum size: 1"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 128,
                "unit": "bytes",
                "source": "annotation"
              },
              {
                "rule": "assert_min_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 1,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "person_user_key",
            "type": "string",
            "description": "person_user_key is WHO, in the form the link registry keys them by:\n \"/tenants/people|\u003cthe person's SPIFFE sub\u003e\" (TenantUserLinks.user_key). The\n registry key rather than a bare user path because it is compared against the\n approving device's own link edges, and that is the form those hold.",
            "required": true,
            "constraints": [
              "maximum size: 1024 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 1024,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "rpc_method",
            "type": "string",
            "description": "rpc_method is WHICH RPC, as \"pkg.Service/Method\" — the qualified method key\n the platform already identifies an RPC by (the generated authorizer's\n _qualified_method_key; kernel's own rate limiter's per-method bucket), i.e.\n gRPC's full method name without its leading slash. Deliberately not a new\n naming scheme and not an entitlement grant name: the generated check has the\n gRPC method in hand and nothing else.",
            "required": true,
            "constraints": [
              "maximum size: 256 bytes",
              "minimum size: 1"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 256,
                "unit": "bytes",
                "source": "annotation"
              },
              {
                "rule": "assert_min_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 1,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "request_hash",
            "type": "bytes",
            "description": "request_hash is a SHA-256 over the EXACT request being approved. Kernel\n treats it as 32 opaque bytes and compares them for equality; WHAT is hashed,\n and how it is canonicalised, is the generator's contract — the same rule has\n to be applied by the proposer and by the generated check, in whatever\n languages each is written in. Kernel never re-derives it, so kernel can\n never silently disagree with either.",
            "required": true,
            "constraints": [
              "maximum size: 64 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 64,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "created_at_ms",
            "type": "int64",
            "constraints": [
              "must be \u003e= 0"
            ],
            "constraint_infos": [
              {
                "rule": "assert_ge",
                "target": "field",
                "value_kind": "int",
                "int_value": 0,
                "source": "annotation"
              }
            ]
          },
          {
            "name": "expires_at_ms",
            "type": "int64",
            "description": "expires_at_ms is kernel's, from a capped TTL, never the caller's number. An\n approval is consent to one call happening NOW; a long-lived one is a\n standing permission, which is the thing §5 exists to refuse.",
            "constraints": [
              "must be \u003e= 0"
            ],
            "constraint_infos": [
              {
                "rule": "assert_ge",
                "target": "field",
                "value_kind": "int",
                "int_value": 0,
                "source": "annotation"
              }
            ]
          },
          {
            "name": "consumed_at_ms",
            "type": "int64",
            "description": "consumed_at_ms burns the approval single-use. Marked rather than deleted so\n a replay inside the window is refused as ALREADY USED rather than as an\n unknown id; the expiry sweep deletes it afterwards. Single-use because a\n guarded RPC need not be idempotent — a captured signature must not be able\n to make the same approved transfer twice.",
            "constraints": [
              "must be \u003e= 0"
            ],
            "constraint_infos": [
              {
                "rule": "assert_ge",
                "target": "field",
                "value_kind": "int",
                "int_value": 0,
                "source": "annotation"
              }
            ]
          },
          {
            "name": "trace_id",
            "type": "string",
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "noop",
            "type": "bool"
          }
        ]
      }
    },
    {
      "name": "total_count",
      "type": "int32"
    },
    {
      "name": "trace_id",
      "type": "string",
      "constraints": [
        "maximum size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
    },
    {
      "name": "noop",
      "type": "bool"
    }
  ]
}

