{
  "name": "Person",
  "package": "kernel",
  "description": "Person is one human: a user row in the reserved `people` tenant, created the\n first time an IdP token for its (provider, provider_subject) pair is seen and\n found on every login after that, from any device or browser.\n\n One provider identity is one person. A human who signs in with both Apple and\n Google is two Person rows until an explicit, both-sides-proven merge exists —\n guessing they are the same human is how accounts get hijacked.",
  "fields": [
    {
      "name": "user_id",
      "type": "string",
      "description": "user_id is the \u003cu\u003e in /tenants/people/users/\u003cu\u003e. It is DERIVED, not minted:\n \"\u003cprovider\u003e.\u003cprovider_subject\u003e\", with the provider drawn from the closed\n enum above (neither `apple` nor `google` contains a '.', so the first dot is\n an unambiguous delimiter). The provider's subject is already stable and\n unique within that provider, so there is no hash of our own to keep\n consistent, and the same human lands on the same row without a lookup\n table.",
      "required": true,
      "constraints": [
        "maximum size: 128 bytes",
        "minimum size: 1"
      ],
      "constraint_infos": [
        {
          "rule": "assert_required",
          "target": "field",
          "value_kind": "bool",
          "bool_value": true,
          "source": "annotation"
        },
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 128,
          "unit": "bytes",
          "source": "annotation"
        },
        {
          "rule": "assert_min_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 1,
          "unit": "bytes",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "provider",
      "type": "enum",
      "description": "provider is which IdP proved this person.",
      "constraint_infos": [
        {
          "rule": "assert_enum_defined",
          "target": "field",
          "value_kind": "bool",
          "bool_value": true,
          "source": "annotation"
        }
      ],
      "enum_values": [
        {
          "name": "PEOPLE_IDP_PROVIDER_APPLE",
          "number": 1,
          "description": "Sign in with Apple (issuer https://appleid.apple.com)."
        },
        {
          "name": "PEOPLE_IDP_PROVIDER_GOOGLE",
          "number": 2,
          "description": "Google Sign-In (issuer https://accounts.google.com)."
        }
      ]
    },
    {
      "name": "provider_subject",
      "type": "string",
      "description": "provider_subject is the IdP's own `sub` claim, verbatim. Never an email:\n an email is reassignable, and comparing them is how one human's rows become\n another's.",
      "required": true,
      "constraints": [
        "maximum size: 128 bytes"
      ],
      "constraint_infos": [
        {
          "rule": "assert_required",
          "target": "field",
          "value_kind": "bool",
          "bool_value": true,
          "source": "annotation"
        },
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 128,
          "unit": "bytes",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "created_at_ms",
      "type": "int64",
      "constraints": [
        "must be \u003e= 0"
      ],
      "constraint_infos": [
        {
          "rule": "assert_ge",
          "target": "field",
