          "int_value": 512,
          "unit": "bytes",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "peer_subject",
      "type": "string",
      "description": "peer_subject is the linked identity's `sub` as kernel mints it. Kernel\n keeps it because peer_namespace alone does not identify a human, and\n because a re-key has to find and rewrite the edge that names one user.",
      "required": true,
      "constraints": [
        "maximum size: 1024 bytes"
      ],
      "constraint_infos": [
        {
          "rule": "assert_required",
          "target": "field",
          "value_kind": "bool",
          "bool_value": true,
          "source": "annotation"
        },
        {
          "rule": "assert_max_size",
          "target": "field",
