{
  "name": "TenantUserLinks",
  "package": "kernel",
  "description": "TenantUserLinks is ONE tenant user's links.\n\n Keyed per user, and written on BOTH sides of every link, deliberately: this\n is read on every user mint, so it must be one O(1) keyed lookup and not a\n scan of every row for one that mentions the caller.",
  "fields": [
    {
      "name": "user_key",
      "type": "string",
      "description": "user_key identifies the linked user as \"\u003cnamespace\u003e|\u003csub\u003e\" — the exact\n namespace and sub claims kernel mints for them. Deliberately the minted\n pair rather than a derived path: an ordinary tenant's `sub` is whatever its\n IdP broker supplies (an email, today) and is not required to be a SPIFFE\n id, so there is no path to derive. The namespace half is what keeps two\n tenants' identically-named users apart.",
      "required": true,
      "constraints": [
        "maximum size: 1024 bytes",
        "minimum size: 1"
      ],
      "constraint_infos": [
        {
          "rule": "assert_required",
          "target": "field",
          "value_kind": "bool",
          "bool_value": true,
          "source": "annotation"
        },
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 1024,
          "unit": "bytes",
          "source": "annotation"
        },
        {
          "rule": "assert_min_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 1,
          "unit": "bytes",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "links",
      "type": "message",
      "repeated": true,
      "constraints": [
        "maximum size: 64 elements"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 64,
          "unit": "elements",
          "source": "annotation"
        }
      ],
      "message": {
        "name": "TenantUserLink",
        "package": "kernel",
        "description": "TenantUserLink is one edge out of a linked tenant user: which identity in\n another tenant is the same human. Linking is GENERIC — any two tenants, not\n `people` and one other. The first use is drpepper's `jody` linked to that\n human's `people` row, but a contractor in two companies and a tenant\n migrating IdPs are the same record.\n\n peer_namespace, not a peer user path, is what the token's `linked` claim\n carries. The generated namespace backstop compares that claim against\n (spec.store_namespace), which holds a NAMESPACE, so a user path would never\n compare equal and a linked caller's read would never be accepted.",
        "fields": [
          {
            "name": "peer_namespace",
            "type": "string",
            "description": "peer_namespace is the canonical /tenants/\u003ct\u003e the linked identity lives in.",
            "required": true,
            "constraints": [
              "maximum size: 512 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 512,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "peer_subject",
            "type": "string",
            "description": "peer_subject is the linked identity's `sub` as kernel mints it. Kernel\n keeps it because peer_namespace alone does not identify a human, and\n because a re-key has to find and rewrite the edge that names one user.",
            "required": true,
            "constraints": [
              "maximum size: 1024 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 1024,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "created_at_ms",
            "type": "int64",
            "constraints": [
              "must be \u003e= 0"
            ],
            "constraint_infos": [
              {
                "rule": "assert_ge",
                "target": "field",
                "value_kind": "int",
                "int_value": 0,
                "source": "annotation"
              }
            ]
          },
          {
            "name": "revoked_at_ms",
            "type": "int64",
            "description": "revoked_at_ms is the unlink mark. Marks, never deletes — the same audit rule\n Grant.revoked_at_ms and PersonalCredential.revoked_at_ms state, and for the\n stronger reason here that a link is proved once by live credentials and\n nothing kernel holds can re-derive it: a deleted edge is indistinguishable\n from one that was never proved.\n\n A revoked edge contributes no `linked` claim at mint. Re-proving the same\n link clears the mark rather than adding a second edge, because the same two\n credentials presented again are the same fact.",
            "constraints": [
              "must be \u003e= 0"
            ],
            "constraint_infos": [
              {
                "rule": "assert_ge",
                "target": "field",
                "value_kind": "int",
                "int_value": 0,
                "source": "annotation"
              }
            ]
          },
          {
            "name": "trace_id",
            "type": "string",
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "noop",
            "type": "bool"
          }
        ]
      }
    },
    {
      "name": "trace_id",
      "type": "string",
      "constraints": [
        "maximum size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "default_max_size",
