          {
            "name": "cluster_name",
            "type": "string",
            "description": "cluster_name is the logical Schematic cluster this kmaker signs for.",
            "required": true,
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
