      "constraints": [
        "maximum size: 128 bytes",
        "minimum size: 1"
      ],
      "constraint_infos": [
        {
          "rule": "assert_required",
          "target": "field",
          "value_kind": "bool",
          "bool_value": true,
          "source": "annotation"
        },
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 128,
          "unit": "bytes",
          "source": "annotation"
        },
        {
          "rule": "assert_min_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 1,
          "unit": "bytes",
          "source": "annotation"
        }
      ],
      "record_key": true
    },
