          "int_value": 0,
          "source": "annotation"
        }
      ]
    },
    {
      "name": "namespace",
      "type": "string",
      "description": "namespace is the row's owning TENANT — mandatory on every record, and copied\n from the same verified caller claim the settings row is stamped from.",
      "constraints": [
        "maximum size: 256 bytes"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 256,
          "unit": "bytes",
          "source": "annotation"
        }
      ],
      "store_namespace": true
    },
    {
