                "target": "field",
                "value_kind": "int",
                "int_value": 1,
                "source": "annotation"
              },
              {
                "rule": "assert_le",
                "target": "field",
                "value_kind": "int",
                "int_value": 256,
                "source": "annotation"
              }
            ]
          },
          {
            "name": "trace_id",
            "type": "string",
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
