                {
                  "name": "token_audience",
                  "type": "string",
                  "description": "token_audience is the required Kubernetes TokenReview audience.",
                  "default": "kmaker",
                  "constraints": [
                    "maximum size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "default_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "kernel_service_accounts",
                  "type": "message",
                  "description": "kernel_service_accounts are Kubernetes service accounts allowed to request\n kernel certificates. Empty means namespace=schematic, name=kernel.",
                  "repeated": true,
                  "constraints": [
                    "maximum size: 32 elements"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 32,
                      "unit": "elements",
                      "source": "annotation"
                    }
                  ],
                  "message": {
                    "name": "KernelServiceAccount",
                    "package": "kmaker",
                    "fields": [
                      {
                        "name": "namespace",
                        "type": "string",
                        "required": true,
                        "constraints": [
                          "maximum size: 128 bytes"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "assert_required",
                            "target": "field",
                            "value_kind": "bool",
                            "bool_value": true,
                            "source": "annotation"
                          },
                          {
                            "rule": "assert_max_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 128,
                            "unit": "bytes",
                            "source": "annotation"
                          }
                        ]
                      },
                      {
                        "name": "name",
                        "type": "string",
                        "required": true,
                        "constraints": [
                          "maximum size: 128 bytes"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "assert_required",
                            "target": "field",
                            "value_kind": "bool",
                            "bool_value": true,
                            "source": "annotation"
                          },
                          {
                            "rule": "assert_max_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 128,
                            "unit": "bytes",
                            "source": "annotation"
                          }
                        ]
                      },
                      {
                        "name": "trace_id",
                        "type": "string",
                        "constraints": [
                          "maximum size: 32768 bytes (default)"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "default_max_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 32768,
                            "defaulted": true,
                            "unit": "bytes",
                            "source": "default_bound"
                          }
                        ]
                      },
                      {
                        "name": "noop",
                        "type": "bool"
                      }
                    ]
                  }
                },
                {
                  "name": "kernel_cert_lifetime_seconds",
                  "type": "int64",
                  "description": "kernel_cert_lifetime_seconds caps issued kernel certificate lifetimes.",
                  "default": 86400,
                  "constraints": [
                    "duration constraint: DURATION_TYPE_POSITIVE"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_duration",
                      "target": "field",
                      "value_kind": "enum",
                      "enum_value": "DURATION_TYPE_POSITIVE",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "tls",
                  "type": "message (recursive reference: x509.X509CertChain)",
                  "description": "tls is the optional serving certificate for kmaker's own gRPC listener.\n When unset, kmaker starts without transport TLS for local/dev only."
                },
                {
                  "name": "health_probe_port",
                  "type": "int32",
                  "description": "health_probe_port is the plaintext gRPC port for k8s health probes.\n Kmaker's hand-written bootstrap bypasses the generated ServiceManager,\n so this field must be on Kmaker.Config (not only on Grpcconfig.Config).\n Default matches the platform-wide health probe port.",
                  "default": 8444
                },
                {
                  "name": "trace_id",
                  "type": "string",
                  "constraints": [
                    "maximum size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "default_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "noop",
                  "type": "bool"
                }
              ]
            }
          },
          {
            "name": "llm_credential",
            "type": "string",
            "description": "llm_credential is a shared secret (e.g. an Anthropic API key) fanned out\n into the generated bootstrap config of every app service named in\n llm_credential_services, under the YAML key \"llm_credential\" — so it is\n configured once here rather than duplicated per app service. The\n receiving app service's own Config must declare a matching field. Keep\n this out of version control — store in crypto.yaml.",
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "llm_credential_services",
            "type": "string",
            "description": "llm_credential_services names the app services (by AppServiceNames key)\n that should receive llm_credential in their generated bootstrap config.",
            "repeated": true,
            "constraints": [
              "maximum size: 64 elements",
              "maximum element size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 64,
                "unit": "elements",
                "source": "annotation"
              },
              {
                "rule": "default_max_element_size",
                "target": "element",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "tenants",
            "type": "string",
            "description": "tenants names the tenants this cluster hosts, e.g. [\"acme\", \"beta\"]. Each\n entry is a bare tenant name; the canonical authorization namespace is\n \"/tenants/\u003cname\u003e\" (see kernel.Delegate.tenant_namespace).\n\n The operator is the single source of truth for the tenant list, the same\n way it is for app_services: nothing queries kernel to discover tenants and\n no second config file lists them. For every service that registry.json\n marks (spec.service).tenant_owned, the operator deploys one Deployment +\n ServiceAccount named \"\u003csvc\u003e-\u003ctenant\u003e\" per entry here, and writes one kernel\n delegate named \u003csvc\u003e with tenant_namespace \"/tenants/\u003cname\u003e\" for each.\n Services NOT marked tenant_owned ignore this field entirely and keep their\n single shared instance.\n\n This does NOT tell a service its own tenant. Tenant identity is derived\n only from the SPIFFE ID in the caller's token at runtime, never from\n config a service can read.",
            "repeated": true,
            "constraints": [
              "maximum size: 64 elements",
              "maximum element size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 64,
                "unit": "elements",
                "source": "annotation"
              },
              {
                "rule": "default_max_element_size",
                "target": "element",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "external_ip",
            "type": "string",
            "description": "external_ip pins the cluster's external LoadBalancer Service to a\n pre-reserved static external address (e.g. a GCP regional compute\n address). It is rendered as spec.loadBalancerIP on the gateway's\n \"\u003cgateway\u003e-lb\" Service — the ONE externally-exposed Service there is,\n carrying TCP/443 and TCP/80 together.\n\n Both ports are on the one Service on purpose: fqdn's public A record\n resolves to this address, and ACME HTTP-01 validation connects to port 80\n on that same name. The gateway answers on 80 and proxies challenge\n requests to the letsencrypt service in-cluster, so letsencrypt needs no\n external address of its own.\n\n Leave empty to let the provider assign an ephemeral address per Service —\n fine for local and dev clusters, but then the address changes on every\n re-render and any DNS record pointing at it goes stale.",
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "extra_hostnames",
            "type": "string",
            "description": "extra_hostnames are public names served IN ADDITION to fqdn (e.g. a second\n domain during a cutover). The operator renders fqdn followed by these into\n the gateway's external_hostnames and letsencrypt's hostnames. fqdn stays\n the primary name: the OIDC issuer and every other single-name use of fqdn\n ignore this field.\n\n Not usable until N-cert/SNI (option b) exists: certmagic issues one\n single-name certificate per name (not one multi-SAN cert), letsencrypt\n publishes only fqdn's, and the gateway has no SNI selection — an extra name\n is served fqdn's certificate and fails TLS name checks. Leave empty.",
            "repeated": true,
            "constraints": [
              "maximum size: 16 elements",
              "maximum element size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 16,
                "unit": "elements",
                "source": "annotation"
              },
              {
                "rule": "default_max_element_size",
                "target": "element",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "image_digests",
            "type": "map",
            "description": "image_digests pins service images by digest. Key is the image name (the\n registry project, equal to the service name for every platform service);\n value is a manifest digest \"sha256:\u003chex\u003e\". A pinned image renders as\n \u003crepository\u003e@\u003cdigest\u003e in place of \u003crepository\u003e:\u003ctag\u003e; an image with no\n entry keeps its tag. Loaded from images.yaml (written by\n scripts/promote.sh), not operator.yaml.",
            "repeated": true,
            "constraints": [
              "maximum size: 256 entries",
              "maximum key size: 32768 bytes (default)",
              "maximum value size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 256,
                "unit": "entries",
                "source": "annotation"
              },
              {
                "rule": "default_max_key_size",
                "target": "key",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              },
              {
                "rule": "default_max_value_size",
                "target": "value",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ],
            "map_key_type": "string",
            "map_value_type": "string"
          },
          {
            "name": "trace_id",
            "type": "string",
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "noop",
            "type": "bool"
          }
        ]
      }
    },
    {
      "name": "trace_id",
      "type": "string",
      "constraints": [
        "maximum size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
    },
    {
      "name": "noop",
      "type": "bool"
    }
  ]
}

fields.description:
InitialFields is a map of fields to include in every log entry
 Useful for adding context like service name, version, environment, etc.
 Example: {"service": "api", "version": "1.0.0", "environment": "production"}

types.schema_json:
{
  "name": "OptionalServices",
  "package": "operator",
  "description": "OptionalServices controls which optional services are enabled.",
  "fields": [
    {
      "name": "oauth",
      "type": "bool",
      "description": "OAuth2/OIDC broker — oauth_nodes replicas when enabled.\n Enabled by default.",
      "default": true
    },
    {
      "name": "keycloak",
      "type": "bool",
      "description": "Keycloak IDP — production identity provider.\n Replaces mockidp. Enabled by default.",
      "default": true
    },
    {
      "name": "echo",
      "type": "bool",
      "description": "Echo sample service — echo_nodes replicas when enabled.\n Disabled by default: it is a diagnostic/reference service, not something a\n production cluster should carry."
    },
    {
      "name": "messaging",
      "type": "bool",
      "description": "Messaging — the platform's message primitive (messaging.proto).\n messaging_nodes replicas when enabled. Disabled by default: it is a\n primitive an application opts into, not something every cluster carries."
    },
    {
      "name": "mailbox",
      "type": "bool",
      "description": "Mailbox — pull delivery and eviction eligibility over messaging's\n deliveries (mailbox.proto). mailbox_nodes replicas when enabled.\n Disabled by default; requires messaging."
    },
    {
      "name": "personalauth",
      "type": "bool",
      "description": "personalauth — the login broker for PERSONAL principals (personalauth.proto).\n Today one arm: DEVICE, a device-held key registering and logging itself in.\n personalauth_nodes replicas when enabled. Disabled by default: a cluster\n whose people all arrive through a tenant IdP has no use for it."
    },
    {
      "name": "blobstore",
      "type": "bool",
      "description": "blobstore — the platform's binary blob primitive (blobstore.proto): a\n two-pod mirror of content-addressed files, with its metadata in stratum\n records. blobstore_nodes replicas when enabled, which is 2.\n\n Disabled by default, and enabling it costs two PersistentVolumeClaims, so a\n cluster whose services declare no volume groups should leave it off — with no\n group declared it would accept no upload anyway (\"no group, no upload\")."
    },
    {
      "name": "harness",
      "type": "bool",
      "description": "harness — the runtime test harness (D27, clients/harness.proto). Not a\n service: a suspended CronJob template \"harness\" running the gate profile,\n which the pipeline starts with `kubectl create job --from=cronjob/harness`.\n Its ServiceAccount has no kernel delegate and its pod mounts no token, so\n it reaches the fleet only through public doors. Disabled by default."
    },
    {
      "name": "harness_destructive",
      "type": "bool",
      "description": "harness_destructive adds the second template, \"harness-destructive\", which\n runs the destructive profile (pod kill, PVC wipe) under a Role that may\n delete only the named blobstore and kernel pods and blobstore PVCs. Dev\n only: never enable it on pilot. Has no effect unless harness is enabled."
    },
    {
      "name": "trace_id",
      "type": "string",
      "constraints": [
        "maximum size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
    },
    {
      "name": "noop",
      "type": "bool"
    }
  ]
}

{
  "name": "PKI",
  "package": "operator",
  "description": "PKI holds all PKI material for the cluster.\n\n root_ca is generated once per organization via 'operator init ca'.\n All other fields are generated per-cluster via 'operator init cluster'.\n PKI material lives in crypto.yaml and is merged into OperatorConfig at\n load time. The crypto.yaml file must be kept secret.",
  "fields": [
    {
      "name": "root_ca",
      "type": "message",
      "description": "Shared root CA across all clusters (cert + private key).",
      "message": {
        "name": "X509CertChain",
        "package": "x509",
        "description": "X509CertChain contains a certificate chain and optional private key.\n chain[0] is the leaf (end-entity) cert, followed by intermediates, ordered toward root.\n When key is present, the chain is a full credential suitable for TLS.",
        "fields": [
          {
            "name": "chain",
            "type": "message",
            "description": "chain[0] is the leaf (end-entity) cert, followed by intermediates, ordered toward root.",
            "repeated": true,
            "constraints": [
              "maximum size: 8 elements",
              "minimum size: 1"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 8,
                "unit": "elements",
                "source": "annotation"
              },
              {
                "rule": "assert_min_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 1,
                "unit": "elements",
                "source": "annotation"
              }
            ],
            "message": {
              "name": "X509Cert",
              "package": "x509",
              "description": "ProtoCert represents an X.509 certificate.\n The certificate is stored as a base64-encoded PEM block.\n Use NewProtoCert() in Go with DER-encoded certificate bytes to create.",
              "fields": [
                {
                  "name": "id",
                  "type": "string",
                  "description": "Id is a unique identifier for the certificate",
                  "constraints": [
                    "maximum size: 256 bytes"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 256,
                      "unit": "bytes",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "base64",
                  "type": "string",
                  "description": "Base64 contains the base64url-encoded PEM certificate block",
                  "required": true,
                  "constraints": [
                    "must be base64 encoded",
                    "maximum size: 16384 bytes"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
