{
  "name": "Topology",
  "package": "operator",
  "description": "Topology declares the desired replica count for each service.\n\n gateway_nodes is special: when set to 0 and mode = IN_CLUSTER, the operator\n automatically sets it to the number of schedulable Kubernetes nodes at each\n reconciliation cycle (one gateway per node). When mode = GENERATE_ONLY,\n gateway_nodes must be set explicitly.",
  "fields": [
    {
      "name": "kernel_nodes",
      "type": "int32",
      "default": 3
    },
    {
      "name": "sentinel_nodes",
      "type": "int32",
      "default": 3
    },
    {
      "name": "eventbus_nodes",
      "type": "int32",
      "default": 3
    },
    {
      "name": "gateway_nodes",
      "type": "int32",
      "description": "Set to 0 to auto-derive from schedulable node count (IN_CLUSTER only).\n When enabled proxy services (anthropic, openai, gitlab, github) also\n scale to one replica per gateway node."
    },
    {
      "name": "oauth_nodes",
      "type": "int32",
      "description": "oauth_nodes is used when optional_services.oauth = true (default).",
      "default": 3
    },
    {
      "name": "opa_nodes",
      "type": "int32",
      "default": 3
    },
    {
      "name": "stratum_nodes",
      "type": "int32",
      "description": "stratum_nodes is the number of WRITER members: the StatefulSet with volumes.\n A writer holds partitions like any member AND persists every write — its redo\n log, its record index, its share of the daily checkpoint — so this is the\n count that decides durability. It is counted for min_durable_copies and for\n the hot-restore barrier, and it is meant to be fairly static (2 or 3).",
      "default": 3
    },
    {
      "name": "stratum_search_nodes",
      "type": "int32",
      "description": "stratum_search_nodes is the number of SEARCH members: a second, volume-less\n workload joining the same Hazelcast cluster with the member attribute\n stratum.role=search.\n\n A search member holds partitions (primaries and backups) and answers the\n parallel scatter-gather a predicate query is, and does nothing else: no\n volume, no redo log, no record index, no checkpoint. It is never a durable\n copy and never a restore contributor, so a search member that leaves loses\n nothing durable and scaling this number up or down changes query throughput\n and nothing about durability.\n\n Defaults to 0: query throughput is a thing a deployment asks for. Raising\n this is NOT a way to raise durability — min_durable_copies counts writers\n (stratum_nodes) only, and a cluster with fewer writers than the floor refuses\n writes however many search members are running."
    },
    {
      "name": "kmaker_nodes",
      "type": "int32",
      "description": "kmaker_nodes is the number of bootstrap certificate authority replicas.\n Kernel instances contact kmaker with Kubernetes projected service account\n tokens to obtain kernel certificates before kernel itself is available.",
      "default": 3
    },
    {
      "name": "echo_nodes",
      "type": "int32",
      "description": "echo_nodes is used when optional_services.echo = true.\n Defaults to 1 rather than 3: the sample service is stateless and exists to\n be poked at, so a second replica proves nothing and costs a pod.",
      "default": 1
    },
    {
      "name": "messaging_nodes",
      "type": "int32",
      "description": "messaging_nodes is used when optional_services.messaging = true.\n Defaults to 1: the service is stateless mediation over eventbus, so a\n second replica buys availability, not throughput, and a cluster that wants\n it says so.",
      "default": 1
    },
    {
      "name": "mailbox_nodes",
      "type": "int32",
      "description": "mailbox_nodes is used when optional_services.mailbox = true.\n Defaults to 1 for the same reason as messaging_nodes.",
      "default": 1
    },
    {
      "name": "personalauth_nodes",
      "type": "int32",
      "description": "personalauth_nodes is used when optional_services.personalauth = true.\n Defaults to 3, not 1: this is the login path for PERSONAL principals, so a\n single replica makes every device registration and every device login\n unavailable for the length of a rollout. Same reasoning, and the same\n count, as oauth_nodes.",
      "default": 3
    },
    {
      "name": "blobstore_nodes",
      "type": "int32",
      "description": "blobstore_nodes is used when optional_services.blobstore = true.\n\n DEFAULTS TO 2, AND 2 IS THE ONLY SUPPORTED VALUE. blobstore is a mirrored\n PAIR: an upload is acked only when both pods have the bytes fsynced, and each\n pod streams to exactly one peer (blob-store-2026-09-25.md R2). The service\n refuses to start if the peer list it is given does not reduce to one peer, so a\n 1 or a 3 here is a cluster that will not come up rather than a cluster that\n quietly degrades. It is a field rather than a constant only so that the\n rendering path is uniform with every other service's.",
      "default": 2
    },
    {
      "name": "app_services",
      "type": "map",
      "description": "app_services declares replica counts for services that are NOT part of the\n platform: an application's own services, defined in the application's proto\n repo and merged into the build.\n\n Every field above is a PLATFORM service with a fixed field number. That is\n fine for the platform, whose service set is what \"the platform\" means — but\n it made the platform unable to host anything else. An application could not\n declare a service without editing this file, and proto3 gives no way to add\n a field to a message from another repo, so \"schematic is reusable\" was not\n true: echo, a sample service, had to take field 17 here to be deployable.\n\n Keyed by service name, so an app adds a service by naming it in its own\n config and this file never changes. Presence with a count \u003e 0 IS the\n enablement — an app service needs no parallel optional_services flag.",
      "repeated": true,
      "constraints": [
        "maximum size: 64 entries",
        "maximum key size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 64,
          "unit": "entries",
          "source": "annotation"
        },
        {
          "rule": "default_max_key_size",
          "target": "key",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ],
      "map_key_type": "string",
      "map_value_type": "int32"
    },
    {
      "name": "trace_id",
      "type": "string",
      "constraints": [
        "maximum size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
    },
    {
      "name": "noop",
      "type": "bool"
    }
  ]
}

