{
  "name": "ScottyActivity",
  "package": "scotty",
  "description": "ScottyActivity is the ARTIFACT left by every write into knowledge.\n\n §1: \"Nothing reaches knowledge without leaving an artifact. Authored facts —\n a phone number, a written policy, a stated deadline — are not distilled from\n anything, so if current state could change with no immutable record, the\n authored half is unrecoverable.\" ScottyState's requires_artifact_on_write\n enforces that this type exists; this is that type.\n\n §4 is the reason it is a generated RECORD rather than something the service\n writes for itself: \"Scotty must not be the writer of the accounting. If it\n were, 'doesn't rat Dennis out' becomes 'can omit'... Accounting is a\n byproduct of the call path, stamped at the generated seam.\" The neutral\n auditor reads THIS, and this carries what was DONE — entity kind, entity id,\n principal, request id — never what was said.\n\n spec.record implies spec.event, so tacplus synthesizes the topic wrapper\n ScottyActivityBus with topic ref scotty.ScottyActivityBus.stream. Do NOT\n hand-write that wrapper.",
  "fields": [
    {
      "name": "activity_id",
      "type": "string",
      "description": "activity_id is the record key: one row per WRITE, not one per entity.",
      "required": true,
      "constraints": [
        "maximum size: 160 bytes",
        "minimum size: 1"
      ],
      "constraint_infos": [
        {
          "rule": "assert_required",
          "target": "field",
          "value_kind": "bool",
          "bool_value": true,
          "source": "annotation"
        },
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 160,
          "unit": "bytes",
          "source": "annotation"
        },
        {
          "rule": "assert_min_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 1,
          "unit": "bytes",
          "source": "annotation"
        }
      ],
      "record_key": true
    },
    {
      "name": "entity_kind",
      "type": "enum",
      "description": "entity_kind and entity_id name what was written. EQ-filterable, because\n \"every artifact for this ticket\" is the question provenance has to answer.",
      "constraint_infos": [
        {
          "rule": "assert_enum_defined",
          "target": "field",
          "value_kind": "bool",
          "bool_value": true,
          "source": "annotation"
        }
      ],
      "enum_values": [
        {
          "name": "SCOTTY_ENTITY_KIND_HUMAN",
          "number": 1
        },
