                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 64,
                "unit": "bytes",
                "source": "annotation"
              },
              {
                "rule": "assert_min_size",
                "target": "field",
