          {
            "name": "nws_place_name",
            "type": "string",
            "description": "A person-readable label NWS returns for the point (\"Houston, TX\"). For\n display only; nothing parses it (scotty design record §5).",
            "constraints": [
              "maximum size: 200 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 200,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "resolved_at_ms",
            "type": "int64",
            "description": "resolved_at_ms is when /points was last asked."
          },
          {
            "name": "superseded_by_place_id",
            "type": "string",
            "description": "superseded_by_place_id: set on the OLD row when NWS re-cut the grid under\n this point. Empty on the current row. This is the ONE field a Place gains\n after creation, and there is deliberately no rpc that sets it: the service\n writes it through the generated state client (PutPlaces), which is the\n established mechanism for a service writing its own state and needs no verb\n registry exception, because the generated state service is Synthesized by\n construction. VERIFY 3 in the design doc, confirmed.\n\n The caveat that comes with it, worth carrying: PutPlaces REPLACES the whole\n row (there is no compare-and-swap). Fine for a single-writer poller; not\n once a second writer exists.",
            "constraints": [
              "maximum size: 64 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 64,
                "unit": "bytes",
