        "name": "RetryConfig",
        "package": "httpclient",
        "description": "RetryConfig configures retry behavior for HTTP requests with jittered exponential backoff.\n This configuration controls how failed requests are retried, including which errors\n and status codes trigger retries, and the backoff timing between attempts.",
        "fields": [
          {
            "name": "max_retries",
