{
  "name": "PullPlaceResponse",
  "package": "query",
  "fields": [
    {
      "name": "items",
      "type": "message",
      "repeated": true,
      "constraints": [
        "maximum size: 1024 elements (default)"
      ],
      "constraint_infos": [
        {
          "rule": "default_max_size",
