            ],
            "enum_values": [
              {
                "name": "TASK_KIND_APPROVE",
                "number": 1
              },
              {
                "name": "TASK_KIND_CALL",
                "number": 2
              },
              {
                "name": "TASK_KIND_TODO",
                "number": 3
              },
              {
                "name": "TASK_KIND_REMINDER",
