        }
      ]
    },
    {
      "name": "item",
      "type": "message",
      "message": {
        "name": "UploadSession",
        "package": "blobstore",
        "description": "UploadSession is one upload's durable reservation and audit trail (R9).\n\n IT IS THE AUTHORIZATION FOR THE PUT. The upload token carries nothing: it is\n raw randomness, and this row — keyed by its sha256 — is where the upload's\n terms live. A pod receiving a PUT hashes the token, reads this row, and takes\n the group, namespace, declared hash, size and content type from it. Exactly\n the shape BlobLink gives a `/b/` token (R3, R7); there is no signing key and\n nothing to rotate.\n\n THE COST, STATED: a record reaches stratum on an eventbus publish, which is\n enqueue-and-retry, so a PUT arriving milliseconds after CreateUpload returned\n can find this row missing and be refused. BlobLink has had exactly that race\n since it was written and it is accepted there for the same reason — a caller\n that just asked for the token retries.\n\n This row is ALSO the quota reservation, the expiry sweep that releases it, the\n single-use ledger (state leaves PENDING once), and the answer to \"what was\n uploaded, by whom, when\".",
        "fields": [
          {
            "name": "upload_id",
            "type": "string",
            "description": "upload_id is the record key: the lowercase hex SHA-256 of the raw upload\n token, exactly as BlobLink.token_hash is for a `/b/` token. A PUT hashes\n what arrived in the path and looks up THAT, so the key is not a secret even\n though the path is. It is derived from the token and not from the content\n hash: two tenants uploading the same bytes at the same time are two\n sessions.",
            "required": true,
            "constraints": [
              "maximum size: 128 bytes",
              "minimum size: 1"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 128,
                "unit": "bytes",
                "source": "annotation"
              },
              {
                "rule": "assert_min_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 1,
                "unit": "bytes",
                "source": "annotation"
              }
            ],
            "record_key": true
          },
          {
            "name": "group",
            "type": "string",
            "description": "group, content_hash, size_bytes and content_type are what the upload\n DECLARED. The Blob row carries what actually arrived; the two are compared\n at end of stream and a mismatch fails the upload (R9 step 3).",
            "required": true,
            "constraints": [
              "maximum size: 64 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 64,
                "unit": "bytes",
                "source": "annotation"
              }
            ],
            "filter_mode": "eq"
          },
          {
            "name": "content_hash",
            "type": "string",
            "required": true,
            "constraints": [
              "maximum size: 64 bytes",
              "minimum size: 64"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 64,
                "unit": "bytes",
                "source": "annotation"
              },
              {
                "rule": "assert_min_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 64,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "size_bytes",
            "type": "int64",
            "constraints": [
              "must be \u003e= 0"
            ],
            "constraint_infos": [
              {
                "rule": "assert_ge",
                "target": "field",
                "value_kind": "int",
                "int_value": 0,
                "source": "annotation"
              }
            ]
          },
          {
            "name": "content_type",
            "type": "string",
            "required": true,
            "constraints": [
              "maximum size: 128 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 128,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "reserved_bytes",
            "type": "int64",
            "description": "reserved_bytes is what this session holds against the tenant's group quota\n while it is PENDING. It is the DECLARED size — the only number available\n before the bytes arrive — which is why `max_blob_bytes` is also enforced on\n the wire: the reservation is a promise the stream still has to keep.",
            "constraints": [
              "must be \u003e= 0"
            ],
            "constraint_infos": [
              {
                "rule": "assert_ge",
                "target": "field",
                "value_kind": "int",
                "int_value": 0,
                "source": "annotation"
              }
            ]
          },
          {
            "name": "state",
            "type": "enum",
            "description": "state is the session's terminal answer. See UploadState.",
            "constraint_infos": [
              {
                "rule": "assert_enum_defined",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              }
            ],
            "enum_values": [
              {
                "name": "UPLOAD_STATE_PENDING",
                "number": 1,
                "description": "PENDING: quota is reserved and the token is live. No bytes have been\n promoted."
              },
              {
                "name": "UPLOAD_STATE_COMMITTED",
                "number": 2,
                "description": "COMMITTED: the bytes are fsynced and renamed on both pods and the Blob row\n is published. The reservation became real usage."
              },
              {
                "name": "UPLOAD_STATE_ABORTED",
                "number": 3,
                "description": "ABORTED: CancelUpload, an expiry sweep, or a failed PUT. Temps are gone\n from both pods and the reservation is released."
              }
            ]
          },
          {
            "name": "created_ms",
            "type": "int64",
            "description": "created_ms and expires_ms bound the token. expires_ms is checked when the\n PUT ARRIVES, not while it streams: a 50 MiB upload on a slow link must not\n fail at minute 16 having transferred everything.",
            "constraints": [
              "must be \u003e= 0"
            ],
            "constraint_infos": [
              {
                "rule": "assert_ge",
                "target": "field",
                "value_kind": "int",
                "int_value": 0,
                "source": "annotation"
              }
            ]
          },
          {
            "name": "expires_ms",
            "type": "int64",
            "constraints": [
              "must be \u003e= 0"
            ],
            "constraint_infos": [
              {
                "rule": "assert_ge",
                "target": "field",
                "value_kind": "int",
                "int_value": 0,
                "source": "annotation"
              }
            ],
            "filter_mode": "range"
          },
          {
            "name": "owner_principal",
            "type": "string",
            "description": "owner_principal and namespace are the owning service and owning tenant, as\n on Blob. The reservation is against exactly this pair's group quota.",
            "required": true,
            "constraints": [
              "maximum size: 256 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 256,
                "unit": "bytes",
                "source": "annotation"
              }
            ],
            "filter_mode": "eq",
            "store_principal": true
          },
          {
            "name": "deleted",
            "type": "bool"
          },
          {
            "name": "spiffe_id",
            "type": "string",
            "constraints": [
              "maximum size: 1024 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 1024,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "namespace",
            "type": "string",
            "required": true,
            "constraints": [
              "maximum size: 256 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 256,
                "unit": "bytes",
                "source": "annotation"
              }
            ],
            "filter_mode": "eq",
            "store_namespace": true
          },
          {
            "name": "trace_id",
            "type": "string",
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "noop",
            "type": "bool"
          }
        ]
      }
    },
    {
      "name": "revision",
      "type": "int64"
    },
    {
      "name": "trace_id",
      "type": "string",
      "constraints": [
        "maximum size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
