{
  "name": "WorkActivityWatchChange",
  "package": "query",
  "fields": [
    {
      "name": "type",
      "type": "enum",
      "enum_values": [
        {
          "name": "RECORD_CHANGE_TYPE_ADD",
          "number": 1
        },
        {
          "name": "RECORD_CHANGE_TYPE_MODIFY",
          "number": 2
