          {
            "name": "principal_sub",
            "type": "enum",
            "enum_values": [
              {
                "name": "ENTITLEMENT_LEVEL_ANONYMIZE",
                "number": 1,
                "description": "Replace with a keyed HMAC surrogate. Valid only on string/bytes fields; on any\n other field the generated transform clamps ANONYMIZE up to REDACT."
              },
              {
                "name": "ENTITLEMENT_LEVEL_REDACT",
                "number": 2,
                "description": "Clear the field to its zero value (a message field clears the whole subtree)."
              },
              {
                "name": "ENTITLEMENT_LEVEL_RAW",
                "number": 3,
                "description": "Egress the field raw — the explicit loosening grant (\"this caller is\n permitted to see the value\"). Only ever set from a matching token data grant."
              }
            ]
          },
          {
            "name": "trace_id",
            "type": "string",
            "constraints": [
              "maximum size: 32768 bytes (default)"
