    },
    {
      "name": "auth_type",
      "type": "enum",
      "description": "auth_type determines the credential format kernel returns to the proxy.\n TOKEN_TYPE_JWT (default): kernel returns a signed JWT in the response.\n Unset is treated as TOKEN_TYPE_JWT.",
      "enum_values": [
        {
          "name": "TOKEN_TYPE_JWT",
