            ]
          },
          {
            "name": "created_at_ms",
            "type": "int64"
          },
          {
            "name": "namespace",
            "type": "string",
            "description": "namespace: see ChatSession.namespace. Same field, same open question about\n what claim a personal principal carries, same reason for keeping it.\n\n EQ-queryable since 2026-09-25, because it is now the ONLY pin this record\n has: with no owning principal, the caller's verified namespace is the whole\n of what `require_chat` pins into the store predicate before it asks (the\n same value it compared in-process when these rows came from kernel).",
            "constraints": [
              "maximum size: 256 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
