      "constraints": [
        "maximum size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
    },
    {
      "name": "noop",
      "type": "bool"
    }
  ]
}

