{
  "name": "PullAgentCycleResponse",
  "package": "query",
  "fields": [
    {
      "name": "items",
      "type": "message",
      "repeated": true,
      "constraints": [
        "maximum size: 1024 elements (default)"
      ],
      "constraint_infos": [
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 1024,
          "defaulted": true,
          "unit": "elements",
          "source": "default_bound"
        }
      ],
      "message": {
        "name": "AgentCycle",
        "package": "scottyagent",
        "description": "AgentCycle is one completed loop cycle: what woke it, when, on which\n instance, under which fencing token.\n\n It is the durable history the design record calls the \"Bird's Eye View\" —\n \"an ordinary generated read surface on that record — no new mechanism\". This\n file therefore declares no read RPC for it: the c2s record query plane\n generated from (spec.store_principal) and the query fields below IS that\n surface, and hand-writing a second one would be the drift the typed-contract\n argument exists to prevent.\n\n Append-shaped by construction: the key carries the cycle number, so a cycle\n is a new row and no cycle ever rewrites another.\n\n spec.record implies spec.event, so tacplus synthesizes the topic wrapper\n AgentCycleBus with topic ref scottyagent.AgentCycleBus.stream. Do NOT\n hand-write that wrapper.",
        "fields": [
          {
            "name": "cycle_id",
            "type": "string",
            "description": "cycle_id is the record key: \"\u003cuser\u003e/\u003ccycle\u003e\".",
            "required": true,
            "constraints": [
              "maximum size: 512 bytes",
              "minimum size: 1"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 512,
                "unit": "bytes",
                "source": "annotation"
              },
              {
                "rule": "assert_min_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 1,
                "unit": "bytes",
                "source": "annotation"
              }
            ],
            "record_key": true
          },
          {
            "name": "user",
            "type": "string",
            "description": "user is whose agent ran, and the ROW'S OWNING PRINCIPAL.\n\n (spec.store_principal) is what holds a caller's reads of this record to\n their own rows on the c2s query plane, and it is the reason the Bird's Eye\n View needs no filtering code: \"my cycles\" is the only query the plane will\n answer. `spiffe_id` below is the record's declared owner but holds THIS\n SERVICE's identity (eventbus stamps the publisher), so filtering on that\n would show every user nothing.\n\n The EQ criterion is what carries the filter into the plane's size-only\n RPCs, which return a number over the handle's predicate and no rows for an\n egress filter to narrow.",
            "required": true,
            "constraints": [
              "maximum size: 256 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 256,
                "unit": "bytes",
                "source": "annotation"
              }
            ],
            "filter_mode": "eq",
            "store_principal": true
          },
          {
            "name": "cycle",
            "type": "int64",
            "description": "cycle is this user's monotonic cycle number, the second half of cycle_id.",
            "constraints": [
              "must be \u003e= 0"
            ],
            "constraint_infos": [
              {
                "rule": "assert_ge",
                "target": "field",
                "value_kind": "int",
                "int_value": 0,
                "source": "annotation"
              }
            ]
          },
          {
            "name": "fencing_token",
            "type": "int64",
            "description": "fencing_token is the kernel.FencedLock token this cycle ran under. Carried\n onto the row so the history itself shows the fence: cycles for one user\n must appear in strictly increasing token order, and a row that does not is\n visible evidence of a stale holder that got through.",
            "constraints": [
              "must be \u003e= 0"
            ],
            "constraint_infos": [
              {
                "rule": "assert_ge",
                "target": "field",
                "value_kind": "int",
                "int_value": 0,
                "source": "annotation"
              }
            ]
          },
          {
            "name": "woke_for",
            "type": "message",
            "description": "woke_for is EVERY event this cycle aggregated, in the order they were\n observed — not just the one that started it. That is the aggregation the\n design record asks for, made legible: \"multiple events can land within one\n loop cycle; they are aggregated and processed together\".\n\n Bounded at 256 to match Config.max_events_per_cycle's ceiling.",
            "repeated": true,
            "constraints": [
              "maximum size: 256 elements"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 256,
                "unit": "elements",
                "source": "annotation"
              }
            ],
            "message": {
              "name": "WakeEvent",
              "package": "scottyagent",
              "description": "WakeEvent is ONE thing that woke the loop. A cycle carries every event it\n aggregated, not just the first, so \"why did you wake\" has a complete answer\n even when several arrived at once.",
              "fields": [
                {
                  "name": "reason",
                  "type": "enum",
                  "description": "reason is the trigger kind.",
                  "constraint_infos": [
