          "value_kind": "int",
          "int_value": 1024,
          "defaulted": true,
          "unit": "elements",
          "source": "default_bound"
        }
      ],
      "message": {
        "name": "Blob",
        "package": "blobstore",
        "description": "Blob is one promoted file: bytes that are fsynced and renamed into place on\n BOTH pods. A Blob row never points at bytes that are not on both pods (R9).\n\n IMMUTABLE AND CONTENT-ADDRESSED, PER TENANT (R5). Identity is\n `(group, namespace, content_hash)` and dedup is within a tenant and group\n only: two tenants holding the same bytes hold two files and each pays. A\n global key would have been a cross-tenant content oracle — ask whether a hash\n exists and learn that someone else has the document — and it contradicted\n DocHashIndex's own per-namespace rule.\n\n NO VERSIONING. A new version is a new blob and the consumer moves its own\n pointer. The filename is the consumer's and lives on BlobLink, not here.",
        "fields": [
          {
            "name": "blob_id",
            "type": "string",
            "description": "blob_id is the record key and the file's path: `\u003cgroup\u003e/\u003cns\u003e/\u003csha256-hex\u003e`.\n Carried as one string rather than derived on read because it IS the key,\n and a key a reader has to assemble from three fields is a key two callers\n can assemble differently.",
            "required": true,
            "constraints": [
              "maximum size: 512 bytes",
              "minimum size: 1"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 512,
                "unit": "bytes",
                "source": "annotation"
              },
              {
                "rule": "assert_min_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 1,
                "unit": "bytes",
                "source": "annotation"
              }
            ],
            "record_key": true
          },
          {
            "name": "group",
            "type": "string",
            "description": "group is the volume group this blob belongs to — the group whose rules\n admitted it. EQ-filterable because per-group quota accounting is a query\n over exactly this field plus `namespace`.",
            "required": true,
            "constraints": [
              "maximum size: 64 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 64,
                "unit": "bytes",
                "source": "annotation"
              }
            ],
            "filter_mode": "eq"
          },
          {
            "name": "content_hash",
            "type": "string",
            "description": "content_hash is the lowercase hex SHA-256 of the bytes, computed by this\n service AS THE UPLOAD STREAMS — native and exact. It is checked against the\n client's declared hash at end of stream and the upload fails if they\n differ (R9 step 3).",
            "required": true,
            "constraints": [
              "maximum size: 64 bytes",
              "minimum size: 64"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 64,
                "unit": "bytes",
                "source": "annotation"
              },
              {
                "rule": "assert_min_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 64,
                "unit": "bytes",
                "source": "annotation"
              }
            ],
            "filter_mode": "eq"
          },
          {
            "name": "size_bytes",
            "type": "int64",
            "description": "size_bytes is the byte count as counted on the wire, not as declared.",
            "constraints": [
              "must be \u003e= 0"
            ],
            "constraint_infos": [
              {
                "rule": "assert_ge",
                "target": "field",
                "value_kind": "int",
                "int_value": 0,
                "source": "annotation"
              }
            ]
          },
          {
            "name": "content_type",
            "type": "string",
            "description": "content_type is what `GET /b/` serves. It survived both the group's\n allow-list and the magic-byte sniff, so it describes the stored bytes\n rather than merely what the uploader said about them.",
            "required": true,
            "constraints": [
              "maximum size: 128 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 128,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "created_ms",
            "type": "int64",
            "description": "created_ms is when the blob was promoted. RANGE-filterable: \"what landed\n this week\" is a question about this field, and it is what a later GC over\n consumers' pointers (R12) would scan.",
            "constraints": [
              "must be \u003e= 0"
            ],
            "constraint_infos": [
              {
                "rule": "assert_ge",
                "target": "field",
                "value_kind": "int",
                "int_value": 0,
                "source": "annotation"
              }
            ],
            "filter_mode": "range"
          },
          {
            "name": "owner_principal",
            "type": "string",
            "description": "owner_principal is the OWNING SERVICE identity — docmanager, not blobstore\n — and the row's owning principal (R6). Only this identity creates or\n revokes links or deletes the blob.\n\n `spiffe_id` below is the record's declared owner but is the PUBLISHER,\n which is always blobstore, so it is the wrong field to filter an owner's\n reads on — the same split mailbox.MailboxEntry makes between `recipient`\n and `spiffe_id`.",
            "required": true,
            "constraints": [
              "maximum size: 256 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 256,
                "unit": "bytes",
                "source": "annotation"
              }
            ],
            "filter_mode": "eq",
            "store_principal": true
          },
          {
            "name": "deleted",
            "type": "bool",
            "description": "deleted marks the blob logically gone. The BYTES are not deleted by the\n record: the owner's Delete is what unlinks them from both pods, and this\n flag is what stops a resolve and starts the purge clock."
          },
          {
            "name": "spiffe_id",
            "type": "string",
            "description": "spiffe_id is the record's owner in the store's sense — the publisher, which\n is blobstore's own workload identity. See owner_principal.",
            "constraints": [
              "maximum size: 1024 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 1024,
                "unit": "bytes",
                "source": "annotation"
              }
            ],
            "filter_mode": "eq"
          },
          {
            "name": "namespace",
            "type": "string",
            "description": "namespace is the OWNING TENANT (R6) and the second segment of blob_id. It\n is what makes dedup per-tenant: the same bytes under two namespaces are two\n rows and two files.",
            "required": true,
            "constraints": [
              "maximum size: 256 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 256,
                "unit": "bytes",
                "source": "annotation"
              }
            ],
            "filter_mode": "eq",
            "store_namespace": true
          },
          {
            "name": "trace_id",
            "type": "string",
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "noop",
            "type": "bool"
          }
        ]
      }
    },
    {
      "name": "next_page_token",
      "type": "string",
      "constraints": [
        "maximum size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
    },
    {
      "name": "total_count",
      "type": "int64"
    },
    {
      "name": "trace_id",
      "type": "string",
      "constraints": [
        "maximum size: 32768 bytes (default)"
