            "constraints": [
              "maximum size: 256 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 256,
                "unit": "bytes",
                "source": "annotation"
              }
            ],
            "filter_mode": "eq"
          },
          {
