          {
            "name": "station_id",
            "type": "string",
            "description": "station_id is the nearest NWS observation station (e.g. \"KHOU\").\n Observations are per STATION, not per gridpoint — a distinction NWS makes\n and this file keeps rather than flattening.",
            "constraints": [
              "maximum size: 32 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
