                "target": "field",
                "value_kind": "int",
                "int_value": 128,
                "unit": "bytes",
                "source": "annotation"
              },
              {
                "rule": "assert_min_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 1,
                "unit": "bytes",
                "source": "annotation"
              }
            ],
            "record_key": true
          },
          {
            "name": "group",
