      "message": {
        "name": "Message",
        "package": "messaging",
        "description": "Message is ONE DELIVERY: one message, to one recipient.\n\n It is NOT one row per submission. A submission naming three recipients\n becomes three `Message` rows sharing a `message_id`, differing in\n `delivery_id` and `recipient`, each independently consumable and\n independently ACKable. See the fan-out note at the top of this file for why\n EventBus cannot do that split itself.\n\n spec.record implies spec.event, so tacplus synthesizes the topic wrapper\n MessageBus with topic ref messaging.MessageBus.stream. Do NOT hand-write that\n wrapper.",
        "fields": [
          {
            "name": "delivery_id",
            "type": "string",
            "description": "delivery_id is the record key: \"\u003cmessage_id\u003e/\u003crecipient\u003e\". One per\n (message, recipient) pair, which is what makes the N publishes of one\n submission N separately-keyed records rather than N copies of one.\n\n Derived rather than random ON PURPOSE: the value a caller would need to\n reconstruct to ACK a delivery is exactly (which message, for whom), so\n deriving it means an agent that knows both never has to have been told the\n id. It is also what makes the fan-out replay-safe — a retried submission\n regenerates the same delivery ids rather than a second set of rows.",
            "required": true,
            "constraints": [
              "maximum size: 512 bytes",
              "minimum size: 1"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 512,
                "unit": "bytes",
                "source": "annotation"
              },
              {
                "rule": "assert_min_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 1,
                "unit": "bytes",
                "source": "annotation"
              }
            ],
            "record_key": true
          },
          {
            "name": "message_id",
            "type": "string",
            "description": "message_id groups the N deliveries of ONE submission. EQ-filterable,\n because \"every delivery of the message I sent\" is the question a sender\n asks, and it is the only way back from a delivery to its siblings.",
            "required": true,
            "constraints": [
              "maximum size: 128 bytes"
