            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 128,
